use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

fn to_base64url(bytes: &[u8]) -> String {
    let b64chars: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut result = String::new();
    let mut i = 0;
    while i + 3 <= bytes.len() {
        let n = ((bytes[i] as u32) << 16) | ((bytes[i+1] as u32) << 8) | (bytes[i+2] as u32);
        result.push(b64chars[((n >> 18) & 63) as usize] as char);
        result.push(b64chars[((n >> 12) & 63) as usize] as char);
        result.push(b64chars[((n >> 6) & 63) as usize] as char);
        result.push(b64chars[(n & 63) as usize] as char);
        i += 3;
    }
    if i + 1 <= bytes.len() {
        let n = (bytes[i] as u32) << 16;
        let n = if i + 1 < bytes.len() { n | ((bytes[i+1] as u32) << 8) } else { n };
        result.push(b64chars[((n >> 18) & 63) as usize] as char);
        result.push(b64chars[((n >> 12) & 63) as usize] as char);
        if i + 1 < bytes.len() {
            result.push(b64chars[((n >> 6) & 63) as usize] as char);
        }
    }
    result
}

fn main() {
    let paths = ["/tmp/test.css", "/tmp/abc.css", "/tmp/test123.css"];

    for path in paths {
        let mut h = DefaultHasher::new();
        h.write(path.as_bytes());
        let hash64 = h.finish();

        // Try base64url of the 8 bytes (big endian)
        let bytes = hash64.to_be_bytes();
        let enc = to_base64url(&bytes);
        println!("{}: h64={:016x}, base64url_8={}", path, hash64, &enc[..6]);

        // Also try little endian
        let bytes_le = hash64.to_le_bytes();
        let enc_le = to_base64url(&bytes_le);
        println!("  le: base64url_8={}", &enc_le[..6]);
    }
}
RUSTEOF
rustc /tmp/hash_test3.rs -o /tmp/hash_test3_bin && /tmp/hash_test3_bin

