        let h = crc32(path.as_bytes());
        if h == *target {
            println!("CRC32 match for {}: {:08x}", path, h);
        }
    }

    // Print actual values for inspection
    println!("\nActual values:");
    for (path, target) in tests {
        let fnv = fnv1a_32(path.as_bytes(), 0x811c9dc5);
        let mm3 = murmur3_32(path.as_bytes(), 0);
        println!("{}: target={:08x}, fnv1a={:08x}, mm3={:08x}", path, target, fnv, mm3);
    }
}

fn fnv1a_32(data: &[u8], seed: u32) -> u32 {
    let mut h = seed;
    for &b in data {
        h ^= b as u32;
        h = h.wrapping_mul(0x01000193);
    }
    h
}

fn murmur3_32(data: &[u8], seed: u32) -> u32 {
    let c1: u32 = 0xcc9e2d51;
    let c2: u32 = 0x1b873593;
    let mut h = seed;
    let blocks = data.len() / 4;

    for i in 0..blocks {
        let k = u32::from_le_bytes([data[i*4], data[i*4+1], data[i*4+2], data[i*4+3]]);
        let k = k.wrapping_mul(c1).rotate_left(15).wrapping_mul(c2);
        h ^= k;
        h = h.rotate_left(13).wrapping_mul(5).wrapping_add(0xe6546b64);
    }

    let tail = &data[blocks*4..];
    let mut k: u32 = 0;
    if tail.len() >= 3 { k ^= (tail[2] as u32) << 16; }
    if tail.len() >= 2 { k ^= (tail[1] as u32) << 8; }
    if tail.len() >= 1 {
        k ^= tail[0] as u32;
        k = k.wrapping_mul(c1).rotate_left(15).wrapping_mul(c2);
        h ^= k;
    }

    h ^= data.len() as u32;
    h ^= h >> 16;
    h = h.wrapping_mul(0x85ebca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    h
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}
