            seed.wrapping_sub(PRIME1),
        );
        while pos + 16 <= len {
            let lane = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
            v1 = v1.wrapping_add(lane.wrapping_mul(PRIME2)).rotate_left(13).wrapping_mul(PRIME1);
            pos += 4;
            let lane = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
            v2 = v2.wrapping_add(lane.wrapping_mul(PRIME2)).rotate_left(13).wrapping_mul(PRIME1);
            pos += 4;
            let lane = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
            v3 = v3.wrapping_add(lane.wrapping_mul(PRIME2)).rotate_left(13).wrapping_mul(PRIME1);
            pos += 4;
            let lane = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
            v4 = v4.wrapping_add(lane.wrapping_mul(PRIME2)).rotate_left(13).wrapping_mul(PRIME1);
            pos += 4;
        }
        v1.rotate_left(1).wrapping_add(v2.rotate_left(7)).wrapping_add(v3.rotate_left(12)).wrapping_add(v4.rotate_left(18))
    } else {
        seed.wrapping_add(PRIME5)
    };
    h32 = h32.wrapping_add(len as u32);
    while pos + 4 <= len {
        let lane = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
        h32 = h32.wrapping_add(lane.wrapping_mul(PRIME3)).rotate_left(17).wrapping_mul(PRIME4);
        pos += 4;
    }
    while pos < len {
        h32 = h32.wrapping_add((data[pos] as u32).wrapping_mul(PRIME5)).rotate_left(11).wrapping_mul(PRIME1);
        pos += 1;
    }
    h32 ^= h32 >> 15;
    h32 = h32.wrapping_mul(PRIME2);
    h32 ^= h32 >> 13;
    h32 = h32.wrapping_mul(PRIME3);
    h32 ^= h32 >> 16;
    h32
}

