use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;
use std::path::Path;

fn main() {
    let pairs: &[(&str, &str)] = &[
        ("/workspace", "/tmp/test.css"),
        ("/tmp", "/tmp/test.css"),
    ];

    for (cwd, input) in pairs {
        let cwd_path = Path::new(cwd);
        let input_path = Path::new(input);

        // Try different path operations
        // Relative path
        let rel = pathdiff(input_path, cwd_path);
        println!("From {}: rel={:?}", cwd, rel);

        // Hash the relative path string
        if let Some(rel_str) = rel.as_ref().and_then(|p| p.to_str()) {
            let mut h = DefaultHasher::new();
            rel_str.hash(&mut h);
            let hash = h.finish();
            println!("  hash(rel_str)={:016x}", hash);

            // Hash just the bytes
            let mut h2 = DefaultHasher::new();
            h2.write(rel_str.as_bytes());
            let hash2 = h2.finish();
            println!("  hash(rel_bytes)={:016x}", hash2);

            // FNV1a
            let fnv = fnv1a_32(rel_str.as_bytes());
            println!("  fnv1a(rel)={:08x}", fnv);
        }
    }
}

fn pathdiff(path: &std::path::Path, base: &std::path::Path) -> Option<std::path::PathBuf> {
    use std::path::Component;
    let mut rel = std::path::PathBuf::new();
    let mut base_components = base.components();
    let mut path_components = path.components();

    loop {
        match (base_components.next(), path_components.next()) {
            (Some(b), Some(p)) => {
                if b == p {
                    continue;
                }
                rel.push("..");
                for _ in base_components.by_ref() { rel.push(".."); }
                rel.push(p.as_os_str());
                for p in path_components.by_ref() { rel.push(p.as_os_str()); }
                return Some(rel);
            }
            (Some(_), None) => return None,
            (None, Some(p)) => {
                rel.push(p.as_os_str());
                for p in path_components.by_ref() { rel.push(p.as_os_str()); }
                return Some(rel);
            }
            (None, None) => return Some(rel),
        }
    }
}

fn fnv1a_32(data: &[u8]) -> u32 {
    let mut h = 0x811c9dc5u32;
    for &b in data {
        h ^= b as u32;
        h = h.wrapping_mul(0x01000193);
    }
    h
}
