// lightningcss - CSS parser, transformer, and minifier
// Version 1.0.0-alpha.70

mod cli;
mod css;

use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process;

fn main() {
    let args = cli::parse_args();

    if args.version {
        println!("lightningcss 1.0.0-alpha.70");
        return;
    }

    if args.help {
        cli::print_help();
        return;
    }

    // Validate arguments
    if args.sourcemap && args.output_file.is_none() && args.output_dir.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>");
        eprintln!();
        eprintln!("USAGE:");
        if let Some(ref css_mod) = args.css_modules {
            eprintln!("    {} --sourcemap <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>> <--css-modules [<CSS_MODULES>]>", args.program_name);
        } else {
            eprintln!("    {} --sourcemap <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>", args.program_name);
        }
        eprintln!();
        eprintln!("For more information try --help");
        process::exit(1);
    }

    if args.input_files.len() > 1 && args.output_file.is_some() {
        eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
        process::exit(1);
    }

    let options = css::ProcessOptions {
        minify: args.minify,
        targets: args.targets.clone(),
        css_modules: args.css_modules.is_some(),
        css_modules_pattern: args.css_modules_pattern.clone(),
        css_modules_dashed_idents: args.css_modules_dashed_idents,
        bundle: args.bundle,
        sourcemap: args.sourcemap,
        error_recovery: args.error_recovery,
        custom_media: args.custom_media,
        browserslist: args.browserslist,
    };

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

    if args.input_files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).expect("Failed to read stdin");

        let pid = process::id();
        let filename = format!("stdin-{}", pid);

        match css::process_css(&input, &filename, &options, &cwd, None) {
            Ok(result) => {
                if args.css_modules.is_some() && args.output_file.is_none() && args.output_dir.is_none() {
                    // Print as JSON
                    let json = format!("{{\"code\":{},\"exports\":{}}}", 
                        json_string(&result.code),
                        result.exports_json);
                    println!("{}", json);
                } else {
                    print!("{}", result.code);
                    if let Some(ref map) = result.sourcemap {
                        print!("\n/*# sourceMappingURL=... */");
                    }
                }
            }
            Err(e) => {
                if args.error_recovery {
                    eprintln!("{}", e);
                } else {
                    let pid = process::id();
                    eprintln!("\nthread 'main' ({}) panicked at src/main.rs:187:45:", pid);
                    eprintln!("called `Result::unwrap()` on an `Err` value: {}", e);
                    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                    process::abort();
                }
            }
        }
    } else {
        // Process files
        for input_file in &args.input_files {
            let input_path = PathBuf::from(input_file);

            let output_path = if let Some(ref dir) = args.output_dir {
                let filename = input_path.file_name().unwrap();
                Some(PathBuf::from(dir).join(filename))
            } else if let Some(ref out) = args.output_file {
                Some(PathBuf::from(out))
