    let path_components: Vec<_> = abs_path.components().collect();
    let base_components: Vec<_> = abs_base.components().collect();

    // Find common prefix
    let common_len = path_components.iter()
        .zip(base_components.iter())
        .take_while(|(p, b)| p == b)
        .count();

    let mut rel = PathBuf::new();

    // Add ".." for each remaining base component
    for _ in base_components.iter().skip(common_len) {
        rel.push("..");
    }

    // Add remaining path components
    for c in path_components.iter().skip(common_len) {
        rel.push(c.as_os_str());
    }

    if rel.as_os_str().is_empty() {
        Some(".".to_string())
    } else {
