                if c2.map(|x| x.is_ascii_digit()).unwrap_or(false) {
                    self.consume_number()
                } else {
                    self.advance();
                    Token { kind: TokenKind::Delim, value: ".".to_string(), pos: start }
                }
            }
            '0'..='9' => self.consume_number(),
            _ => {
                self.advance();
                Token { kind: TokenKind::Delim, value: c.to_string(), pos: start }
            }
        }
    }

    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let is_eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if is_eof { break; }
        }
        tokens
    }
