    fn consume_ident_like(&mut self) -> Token {
        let start = self.pos;
        let name = self.consume_ident_string();

        if self.peek() == Some('(') {
            self.advance();
            // It's a function
            let value = format!("{}(", name);
            if name.eq_ignore_ascii_case("url") {
                // Consume the url token
                let mut url_start = self.pos;
                // Skip whitespace
                while let Some(c) = self.peek() {
                    if c.is_whitespace() { self.advance(); } else { break; }
                }
                if let Some(q) = self.peek() {
                    if q == '"' || q == '\'' {
                        // URL with string
                        let str_tok = self.consume_string(q);
                        // Skip whitespace
                        while let Some(c) = self.peek() {
                            if c.is_whitespace() { self.advance(); } else { break; }
                        }
                        // Expect )
                        if self.peek() == Some(')') {
                            self.advance();
                        }
                        let url_val = str_tok.value;
                        let inner = if url_val.len() >= 2 {
                            url_val[1..url_val.len()-1].to_string()
                        } else {
                            String::new()
                        };
                        return Token {
                            kind: TokenKind::Url,
                            value: inner,
                            pos: start,
                        };
                    }
                }
                // Unquoted URL
                let url_start = self.pos;
                while let Some(c) = self.peek() {
                    if c == ')' || c.is_whitespace() { break; }
                    if c == '\\' {
                        self.advance();
                        self.advance();
                    } else {
                        self.advance();
                    }
                }
                let url_val = self.input[url_start..self.pos].to_string();
                while let Some(c) = self.peek() {
                    if c.is_whitespace() { self.advance(); } else { break; }
                }
                if self.peek() == Some(')') { self.advance(); }
                return Token {
                    kind: TokenKind::Url,
                    value: url_val,
                    pos: start,
                };
            }
            return Token {
                kind: TokenKind::Function,
                value,
                pos: start,
            };
        }

        Token {
            kind: TokenKind::Ident,
            value: name,
            pos: start,
        }
    }

    pub fn consume_ident_string(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '\\' {
                self.advance();
                let esc = self.consume_escape();
                s.push_str(&esc);
            } else if c.is_alphanumeric() || c == '-' || c == '_' || c as u32 > 127 {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    fn would_start_ident(&self) -> bool {
        if let Some(c) = self.peek() {
            if c == '-' {
                if let Some(c2) = self.peek2() {
                    return c2.is_alphabetic() || c2 == '_' || c2 == '-' || c2 as u32 > 127;
                }
                return false;
            }
            return c.is_alphabetic() || c == '_' || c as u32 > 127;
        }
        false
    }

    fn consume_number(&mut self) -> Token {
        let start = self.pos;
        let mut num = String::new();

        // Optional sign
        if let Some(c) = self.peek() {
            if c == '+' || c == '-' {
                num.push(c);
                self.advance();
            }
        }

        // Integer part
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                num.push(c);
                self.advance();
            } else {
                break;
            }
        }

        // Decimal part
        if self.peek() == Some('.') {
            if let Some(c) = self.input[self.pos+1..].chars().next() {
                if c.is_ascii_digit() {
                    num.push('.');
                    self.advance();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            num.push(c);
                            self.advance();
                        } else {
                            break;
                        }
                    }
                }
            }
        }

        // Exponent
        if let Some(e) = self.peek() {
            if e == 'e' || e == 'E' {
                let mut tmp_pos = self.pos;
                let mut tmp = String::new();
                tmp.push(e);
                // Check next char
                let remaining = &self.input[self.pos+1..];
                let mut chars = remaining.chars();
                if let Some(next) = chars.next() {
                    if next == '+' || next == '-' {
                        tmp.push(next);
                        if let Some(d) = chars.next() {
                            if d.is_ascii_digit() {
                                num.push_str(&tmp);
                                self.advance(); // e/E
                                self.advance(); // sign
                                num.push(d);
                                self.advance(); // first digit
                                while let Some(c) = self.peek() {
                                    if c.is_ascii_digit() {
                                        num.push(c);
                                        self.advance();
                                    } else { break; }
                                }
                            }
                        }
                    } else if next.is_ascii_digit() {
                        num.push(e);
                        self.advance(); // e/E
                        while let Some(c) = self.peek() {
                            if c.is_ascii_digit() {
                                num.push(c);
                                self.advance();
                            } else { break; }
                        }
                    }
                }
            }
        }

        // Check for unit
        if self.would_start_ident() {
            let unit = self.consume_ident_string();
            return Token {
                kind: TokenKind::Dimension,
                value: format!("{}{}", num, unit),
                pos: start,
            };
        }

        // Check for percentage
        if self.peek() == Some('%') {
            self.advance();
            return Token {
                kind: TokenKind::Percentage,
                value: format!("{}%", num),
                pos: start,
            };
        }

        Token {
            kind: TokenKind::Number,
            value: num,
            pos: start,
        }
    }

    pub fn next_token(&mut self) -> Token {
        let start = self.pos;

        if self.pos >= self.input.len() {
            return Token { kind: TokenKind::Eof, value: String::new(), pos: start };
        }

        // Whitespace
        if let Some(c) = self.peek() {
            if c.is_whitespace() {
                return self.consume_whitespace();
            }
        }

        // Comment
        if let Some(tok) = self.consume_comment() {
            return tok;
        }

        let c = match self.peek() {
            Some(c) => c,
            None => return Token { kind: TokenKind::Eof, value: String::new(), pos: start },
        };

        match c {
            '"' | '\'' => self.consume_string(c),
            '#' => {
                self.advance();
                let name = self.consume_ident_string();
                Token {
                    kind: TokenKind::Hash,
                    value: format!("#{}", name),
                    pos: start,
                }
            }
            '@' => {
                self.advance();
                let name = self.consume_ident_string();
                Token {
                    kind: TokenKind::AtKeyword,
                    value: format!("@{}", name),
                    pos: start,
                }
            }
            ':' => { self.advance(); Token { kind: TokenKind::Colon, value: ":".to_string(), pos: start } }
            ';' => { self.advance(); Token { kind: TokenKind::Semicolon, value: ";".to_string(), pos: start } }
            ',' => { self.advance(); Token { kind: TokenKind::Comma, value: ",".to_string(), pos: start } }
            '[' => { self.advance(); Token { kind: TokenKind::LBracket, value: "[".to_string(), pos: start } }
            ']' => { self.advance(); Token { kind: TokenKind::RBracket, value: "]".to_string(), pos: start } }
            '(' => { self.advance(); Token { kind: TokenKind::LParen, value: "(".to_string(), pos: start } }
            ')' => { self.advance(); Token { kind: TokenKind::RParen, value: ")".to_string(), pos: start } }
            '{' => { self.advance(); Token { kind: TokenKind::LCurly, value: "{".to_string(), pos: start } }
            '}' => { self.advance(); Token { kind: TokenKind::RCurly, value: "}".to_string(), pos: start } }
            _ if c.is_alphabetic() || c == '_' || c as u32 > 127 => {
                self.consume_ident_like()
            }
            '-' => {
                if self.would_start_ident() {
                    self.consume_ident_like()
                } else {
                    let c2 = self.peek2();
                    if c2.map(|x| x.is_ascii_digit() || x == '.').unwrap_or(false) {
                        self.consume_number()
                    } else {
                        self.advance();
                        Token { kind: TokenKind::Delim, value: "-".to_string(), pos: start }
                    }
                }
            }
            '+' => {
                let c2 = self.peek2();
                if c2.map(|x| x.is_ascii_digit() || x == '.').unwrap_or(false) {
                    self.consume_number()
                } else {
                    self.advance();
                    Token { kind: TokenKind::Delim, value: "+".to_string(), pos: start }
                }
            }
            '.' => {
                let c2 = self.peek2();
                if c2.map(|x| x.is_ascii_digit()).unwrap_or(false) {
                    self.consume_number()
                } else {
                    self.advance();
                    Token { kind: TokenKind::Delim, value: ".".to_string(), pos: start }
                }
            }
            '0'..='9' => self.consume_number(),
            _ => {
                self.advance();
                Token { kind: TokenKind::Delim, value: c.to_string(), pos: start }
            }
        }
    }

    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let is_eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if is_eof { break; }
        }
        tokens
    }
}
