pub fn component_values_to_string(values: &[ComponentValue]) -> String {
    let mut s = String::new();
    for v in values {
        match v {
            ComponentValue::Token(t) => s.push_str(&t.value),
            ComponentValue::Function(name, args) => {
                s.push_str(name);
                s.push_str(&component_values_to_string(args));
                s.push(')');
            }
            ComponentValue::Block(kind, inner) => {
                let (open, close) = match kind {
                    BlockKind::Curly => ("{", "}"),
                    BlockKind::Square => ("[", "]"),
                    BlockKind::Paren => ("(", ")"),
                };
                s.push_str(open);
                s.push_str(&component_values_to_string(inner));
                s.push_str(close);
            }
        }
    }
