struct Parser<'a> {
    tokens: Vec<Token>,
    pos: usize,
    filename: &'a str,
}

impl<'a> Parser<'a> {
    fn new(tokens: Vec<Token>, filename: &'a str) -> Self {
        Parser { tokens, pos: 0, filename }
    }

    fn peek(&self) -> &Token {
        // Skip whitespace and comments
        let mut i = self.pos;
        while i < self.tokens.len() {
            match self.tokens[i].kind {
                TokenKind::Whitespace | TokenKind::Comment => i += 1,
                _ => return &self.tokens[i],
            }
        }
        self.tokens.last().unwrap()
    }

    fn peek_with_ws(&self) -> &Token {
        if self.pos < self.tokens.len() {
            &self.tokens[self.pos]
        } else {
            self.tokens.last().unwrap()
        }
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.pos];
        self.pos += 1;
        tok
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.tokens.len() {
            match self.tokens[self.pos].kind {
                TokenKind::Whitespace | TokenKind::Comment => self.pos += 1,
                _ => break,
            }
        }
    }

    fn expect(&mut self, kind: TokenKind) -> Result<Token, CssError> {
        self.skip_whitespace();
        if self.pos < self.tokens.len() && self.tokens[self.pos].kind == kind {
            let tok = self.tokens[self.pos].clone();
            self.pos += 1;
            Ok(tok)
        } else {
            let tok = &self.tokens[self.pos.min(self.tokens.len()-1)];
            let (line, col) = position_from_token(tok, self.filename);
            Err(CssError::ParseError(format!(
                "Error {{ kind: UnexpectedToken({:?}), loc: Some(ErrorLocation {{ filename: {:?}, line: {}, column: {} }} ) }}",
                tok.value, self.filename, line, col
            )))
        }
    }

    fn current_position(&self) -> (u32, u32) {
        if self.pos < self.tokens.len() {
            let tok = &self.tokens[self.pos];
            (0, tok.pos as u32)
        } else {
            (0, 0)
        }
    }

    fn parse_stylesheet(&mut self) -> Result<Vec<Rule>, CssError> {
        let mut rules = Vec::new();

        loop {
            self.skip_whitespace();
            if self.peek().kind == TokenKind::Eof {
                break;
            }

            match self.peek().kind {
                TokenKind::AtKeyword => {
                    let rule = self.parse_at_rule()?;
                    if let Some(r) = rule {
                        rules.push(r);
                    }
                }
                TokenKind::Eof => break,
                _ => {
                    let rule = self.parse_qualified_rule(false)?;
                    if let Some(r) = rule {
                        rules.push(r);
                    }
                }
            }
        }

        Ok(rules)
    }

    fn parse_at_rule(&mut self) -> Result<Option<Rule>, CssError> {
        self.skip_whitespace();
        let at_token = self.advance().clone();
        let at_name = at_token.value.clone();

        self.skip_whitespace();

        match at_name.to_lowercase().trim_start_matches('@') {
            "charset" => {
                // @charset "...";
                self.skip_whitespace();
                let _str_token = self.advance(); // skip the string
                self.skip_whitespace();
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                }
                // Ignore @charset
                return Ok(None);
            }
            "import" => {
                self.skip_whitespace();
                let mut url = String::new();
                // Parse the URL
                let tok = self.peek().clone();
                match tok.kind {
                    TokenKind::String => {
                        url = tok.value[1..tok.value.len()-1].to_string();
                        self.skip_whitespace();
                        self.advance();
                    }
                    TokenKind::Url => {
                        url = tok.value.clone();
                        self.skip_whitespace();
                        self.advance();
                    }
                    TokenKind::Function if tok.value.eq_ignore_ascii_case("url(") => {
                        self.advance();
                        self.skip_whitespace();
                        let str_tok = self.advance().clone();
                        url = if str_tok.kind == TokenKind::String {
                            str_tok.value[1..str_tok.value.len()-1].to_string()
                        } else {
                            str_tok.value.clone()
                        };
                        self.skip_whitespace();
                        let _closing = self.advance();
                    }
                    _ => {
                        url = tok.value.clone();
                        self.advance();
                    }
                }
                // Skip to semicolon
                while self.peek().kind != TokenKind::Semicolon && self.peek().kind != TokenKind::Eof {
                    self.advance();
                }
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                }
                return Ok(Some(Rule::AtRule(AtRule {
                    kind: AtRuleKind::Import(url),
                    prelude: String::new(),
                    block: None,
                    declarations: None,
                })));
            }
            "media" => {
                let prelude = self.parse_prelude_until_block();
                self.skip_whitespace();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let inner_rules = self.parse_stylesheet_block()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Media(MediaQuery { raw: prelude.clone(), queries: vec![prelude] }),
                        prelude: String::new(),
                        block: Some(inner_rules),
                        declarations: None,
                    })));
                }
            }
            "supports" => {
                let prelude = self.parse_prelude_until_block();
                self.skip_whitespace();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let inner_rules = self.parse_stylesheet_block()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Supports(prelude),
                        prelude: String::new(),
                        block: Some(inner_rules),
                        declarations: None,
                    })));
                }
            }
            "keyframes" | "-webkit-keyframes" | "-moz-keyframes" | "-o-keyframes" | "-ms-keyframes" => {
                self.skip_whitespace();
                let name = self.consume_identifier_or_string();
                let vendor = if at_name.contains("-webkit-") { "webkit" }
                    else if at_name.contains("-moz-") { "moz" }
                    else if at_name.contains("-o-") { "o" }
                    else if at_name.contains("-ms-") { "ms" }
                    else { "" };
                self.skip_whitespace();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let inner_rules = self.parse_keyframes_block()?;
                    let at_name_str = format!("@keyframes {}", name);
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Keyframes(name),
                        prelude: vendor.to_string(),
                        block: Some(inner_rules),
                        declarations: None,
                    })));
                }
            }
            "font-face" => {
                self.skip_whitespace();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let decls = self.parse_declarations()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::FontFace,
                        prelude: String::new(),
                        block: None,
                        declarations: Some(decls),
                    })));
                }
            }
            "layer" => {
                self.skip_whitespace();
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Layer(None),
                        prelude: String::new(),
                        block: None,
                        declarations: None,
                    })));
                } else if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let inner_rules = self.parse_stylesheet_block()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Layer(Some(vec![])),
                        prelude: String::new(),
                        block: Some(inner_rules),
                        declarations: None,
                    })));
                } else {
                    // Layer list: @layer base, utilities;
                    let prelude = self.parse_prelude_until_semicolon_or_block();
                    if self.peek().kind == TokenKind::Semicolon {
                        self.advance();
                        let names: Vec<String> = prelude.split(',').map(|s| s.trim().to_string()).collect();
                        return Ok(Some(Rule::AtRule(AtRule {
                            kind: AtRuleKind::Layer(Some(names)),
                            prelude: String::new(),
                            block: None,
                            declarations: None,
                        })));
                    } else if self.peek().kind == TokenKind::LCurly {
                        self.advance();
                        let inner_rules = self.parse_stylesheet_block()?;
                        let name = prelude.trim().to_string();
                        return Ok(Some(Rule::AtRule(AtRule {
                            kind: AtRuleKind::Layer(Some(vec![name])),
                            prelude: String::new(),
                            block: Some(inner_rules),
                            declarations: None,
                        })));
                    }
                }
            }
            "custom-media" => {
                self.skip_whitespace();
                let prelude = self.parse_prelude_until_semicolon_or_block();
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                }
                // Parse: --name (media-query)
                let parts: Vec<&str> = prelude.splitn(2, ' ').collect();
                if parts.len() >= 2 {
                    let name = parts[0].to_string();
                    let query = parts[1..].join(" ").trim().to_string();
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::CustomMedia(name, query),
                        prelude: String::new(),
                        block: None,
                        declarations: None,
                    })));
                }
                return Ok(None);
            }
            "namespace" => {
                let prelude = self.parse_prelude_until_semicolon_or_block();
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                }
                return Ok(Some(Rule::AtRule(AtRule {
                    kind: AtRuleKind::Unknown(at_name),
                    prelude,
                    block: None,
                    declarations: None,
                })));
            }
            "page" => {
                let prelude = self.parse_prelude_until_block();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let decls = self.parse_declarations()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Page(if prelude.trim().is_empty() { None } else { Some(prelude.trim().to_string()) }),
                        prelude: String::new(),
                        block: None,
                        declarations: Some(decls),
                    })));
                }
            }
            "counter-style" => {
                self.skip_whitespace();
                let name = self.consume_identifier_or_string();
                if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    let decls = self.parse_declarations()?;
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::CounterStyle(name),
                        prelude: String::new(),
                        block: None,
                        declarations: Some(decls),
                    })));
                }
            }
            _ => {
                // Unknown at-rule - try to consume it
                let prelude = self.parse_prelude_until_semicolon_or_block();
                if self.peek().kind == TokenKind::Semicolon {
                    self.advance();
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Unknown(at_name),
                        prelude,
                        block: None,
                        declarations: None,
                    })));
                } else if self.peek().kind == TokenKind::LCurly {
                    self.advance();
                    // Skip the block
                    let mut depth = 1;
                    while depth > 0 && self.peek().kind != TokenKind::Eof {
                        match self.peek().kind {
                            TokenKind::LCurly => { depth += 1; self.advance(); }
                            TokenKind::RCurly => { depth -= 1; self.advance(); }
                            _ => { self.advance(); }
                        }
                    }
                    return Ok(Some(Rule::AtRule(AtRule {
                        kind: AtRuleKind::Unknown(at_name),
                        prelude,
                        block: None,
                        declarations: None,
                    })));
                }
            }
        }

        Ok(None)
    }

    fn consume_identifier_or_string(&mut self) -> String {
        self.skip_whitespace();
        let tok = self.peek().clone();
        match tok.kind {
            TokenKind::Ident => {
                self.advance();
                tok.value
            }
            TokenKind::String => {
                self.advance();
                // Strip quotes
                let s = &tok.value;
                if s.starts_with('"') || s.starts_with('\'') {
                    s[1..s.len()-1].to_string()
                } else {
                    s.clone()
                }
            }
            _ => {
                self.advance();
                tok.value
            }
        }
    }

    fn parse_prelude_until_block(&mut self) -> String {
        let mut s = String::new();
        while self.peek().kind != TokenKind::LCurly 
            && self.peek().kind != TokenKind::Eof
            && self.peek().kind != TokenKind::Semicolon {
            // Include whitespace
            let tok = self.tokens[self.pos].clone();
            s.push_str(&tok.value);
            self.pos += 1;
        }
        s.trim().to_string()
    }

    fn parse_prelude_until_semicolon_or_block(&mut self) -> String {
        let mut s = String::new();
        while self.peek().kind != TokenKind::Semicolon 
            && self.peek().kind != TokenKind::LCurly
            && self.peek().kind != TokenKind::Eof {
            let tok = self.tokens[self.pos].clone();
            s.push_str(&tok.value);
            self.pos += 1;
        }
        s.trim().to_string()
    }

    fn parse_stylesheet_block(&mut self) -> Result<Vec<Rule>, CssError> {
        let mut rules = Vec::new();
        loop {
            self.skip_whitespace();
            match self.peek().kind {
                TokenKind::RCurly => { self.advance(); break; }
                TokenKind::Eof => break,
                TokenKind::AtKeyword => {
                    if let Some(rule) = self.parse_at_rule()? {
                        rules.push(rule);
                    }
                }
                _ => {
                    if let Some(rule) = self.parse_qualified_rule(false)? {
                        rules.push(rule);
                    }
                }
            }
        }
        Ok(rules)
    }

    fn parse_keyframes_block(&mut self) -> Result<Vec<Rule>, CssError> {
        let mut rules = Vec::new();
        loop {
            self.skip_whitespace();
            match self.peek().kind {
                TokenKind::RCurly => { self.advance(); break; }
                TokenKind::Eof => break,
                _ => {
                    // Parse keyframe rule: selector { declarations }
                    if let Some(rule) = self.parse_qualified_rule(true)? {
                        rules.push(rule);
                    }
                }
            }
        }
        Ok(rules)
    }

    fn parse_qualified_rule(&mut self, is_keyframe: bool) -> Result<Option<Rule>, CssError> {
        self.skip_whitespace();

        // Parse selector(s)
        let selectors = if is_keyframe {
            let sel = self.parse_keyframe_selector();
            sel
        } else {
            self.parse_selectors()?
        };

        if selectors.is_empty() && self.peek().kind == TokenKind::RCurly {
            return Ok(None);
        }

        if self.peek().kind != TokenKind::LCurly {
            // Skip to next block or rule
            while self.peek().kind != TokenKind::LCurly 
                && self.peek().kind != TokenKind::Semicolon
                && self.peek().kind != TokenKind::Eof {
                self.advance();
            }
            if self.peek().kind == TokenKind::Semicolon {
                self.advance();
                return Ok(None);
            }
            if self.peek().kind == TokenKind::Eof {
                return Ok(None);
            }
        }

        self.advance(); // {

        // Parse declarations and nested rules
        let (decls, nested) = self.parse_rule_body()?;

        Ok(Some(Rule::Style(StyleRule {
            selectors,
            declarations: decls,
            nested_rules: nested,
        })))
    }

    fn parse_selectors(&mut self) -> Result<Vec<String>, CssError> {
        let mut selectors = Vec::new();
        let mut current = String::new();
        let mut depth = 0i32;

        loop {
            // Advance with whitespace tracking
            let tok = if self.pos < self.tokens.len() {
                self.tokens[self.pos].clone()
            } else {
                break;
            };

            match tok.kind {
                TokenKind::LCurly if depth == 0 => {
                    // Don't consume the {
                    let sel = current.trim().to_string();
                    if !sel.is_empty() {
                        selectors.push(sel);
                    }
                    break;
                }
                TokenKind::Comma if depth == 0 => {
                    self.pos += 1;
                    let sel = current.trim().to_string();
                    if !sel.is_empty() {
                        selectors.push(sel);
                    }
                    current = String::new();
                    // Skip whitespace after comma
                    while self.pos < self.tokens.len() && self.tokens[self.pos].kind == TokenKind::Whitespace {
                        self.pos += 1;
                    }
                }
                TokenKind::Eof => break,
                TokenKind::Semicolon if depth == 0 => break,
                TokenKind::LParen | TokenKind::LBracket | TokenKind::LCurly => {
                    depth += 1;
                    self.pos += 1;
                    current.push_str(&tok.value);
                }
                TokenKind::RParen | TokenKind::RBracket => {
                    depth -= 1;
                    self.pos += 1;
                    current.push_str(&tok.value);
                }
                TokenKind::RCurly if depth > 0 => {
                    depth -= 1;
                    self.pos += 1;
                    current.push_str(&tok.value);
                }
                TokenKind::Comment => {
                    self.pos += 1;
                }
                TokenKind::Whitespace => {
                    self.pos += 1;
                    // Add space if needed
                    if !current.ends_with(' ') && !current.is_empty() {
                        let next_tok = if self.pos < self.tokens.len() { 
                            self.tokens[self.pos].kind.clone()
                        } else { TokenKind::Eof };
                        match next_tok {
                            TokenKind::LCurly | TokenKind::Comma | TokenKind::Eof => {},
                            _ => current.push(' '),
                        }
                    }
                }
                _ => {
                    self.pos += 1;
                    current.push_str(&tok.value);
                }
            }
        }

        // Add any remaining selector
        let sel = current.trim().to_string();
        if !sel.is_empty() && !selectors.contains(&sel) {
            selectors.push(sel);
        }

        Ok(selectors)
    }

    fn parse_keyframe_selector(&mut self) -> Vec<String> {
        let mut selector = String::new();
        loop {
            if self.pos >= self.tokens.len() { break; }
            let tok = self.tokens[self.pos].clone();
            match tok.kind {
                TokenKind::LCurly => break,
                TokenKind::Eof => break,
                TokenKind::Comment => { self.pos += 1; }
                _ => {
                    self.pos += 1;
                    selector.push_str(&tok.value);
                }
            }
        }
        vec![selector.trim().to_string()]
    }

    fn parse_rule_body(&mut self) -> Result<(Vec<Declaration>, Vec<Rule>), CssError> {
        let mut decls = Vec::new();
        let mut nested = Vec::new();

        loop {
            self.skip_whitespace();
            match self.peek().kind {
                TokenKind::RCurly => { self.advance(); break; }
                TokenKind::Eof => break,
                TokenKind::Semicolon => { self.advance(); } // empty declaration
                TokenKind::AtKeyword => {
                    if let Some(rule) = self.parse_at_rule()? {
                        nested.push(rule);
                    }
                }
                _ => {
                    // Try to determine if this is a declaration or a nested rule
                    // Lookahead: if we find ':' before '{', it's a declaration
                    // Unless it looks like a selector (e.g., '& .foo {')
                    if self.looks_like_nested_rule() {
                        if let Some(rule) = self.parse_qualified_rule(false)? {
                            nested.push(rule);
                        }
                    } else {
                        if let Some(decl) = self.parse_declaration()? {
                            decls.push(decl);
                        }
                    }
                }
            }
        }

        Ok((decls, nested))
    }

    fn looks_like_nested_rule(&self) -> bool {
        // Lookahead to see if the next token sequence is a selector
        let mut i = self.pos;
        let mut depth = 0i32;
        let mut found_colon = false;
        let mut found_open_brace = false;

        while i < self.tokens.len() {
            match self.tokens[i].kind {
                TokenKind::Eof => break,
                TokenKind::RCurly if depth == 0 => break,
                TokenKind::LCurly if depth == 0 => {
                    found_open_brace = true;
                    break;
                }
                TokenKind::LCurly | TokenKind::LParen | TokenKind::LBracket => {
                    depth += 1;
                }
                TokenKind::RCurly | TokenKind::RParen | TokenKind::RBracket => {
                    depth -= 1;
                }
                TokenKind::Colon if depth == 0 => {
                    // Could be pseudo-selector or property
                    // Check if next non-ws token is an ident that's not a known pseudo
                    let j = i + 1;
                    let mut k = j;
                    while k < self.tokens.len() && self.tokens[k].kind == TokenKind::Whitespace {
                        k += 1;
                    }
                    if k < self.tokens.len() {
                        let next = &self.tokens[k];
                        // If it's followed by a selector char or known pseudo, it's a selector
                        match next.kind {
                            TokenKind::Colon => {
                                // ::pseudo - nested rule
                                return true;
                            }
                            _ => {}
                        }
                    }
                    found_colon = true;
                }
                TokenKind::Semicolon if depth == 0 => {
                    // Declaration
                    return false;
                }
                _ => {}
            }
            i += 1;
        }

        if found_open_brace {
            // Check for CSS nesting: & selector, .class, #id, [attr], :pseudo, etc.
            let first = &self.tokens[self.pos];
            match first.kind {
                TokenKind::Delim if first.value == "&" => return true,
                TokenKind::Delim if first.value == "." => return true,
                TokenKind::Hash => return true,
                TokenKind::Colon => return true,
                _ => {
                    // If there's a colon AND a brace, might still be nested or declaration
                    // If colon before brace, likely declaration unless it looks selector-ish
                    return !found_colon;
                }
            }
        }

        false
    }

    fn parse_declaration(&mut self) -> Result<Option<Declaration>, CssError> {
        self.skip_whitespace();

        // Parse property name
        let prop_tok = self.tokens.get(self.pos).cloned();
        if prop_tok.is_none() {
            return Ok(None);
        }
        let prop_tok = prop_tok.unwrap();

        let property = match prop_tok.kind {
            TokenKind::Ident => {
                self.pos += 1;
                prop_tok.value.clone()
            }
            TokenKind::Hash if prop_tok.value.starts_with("--") => {
                // CSS custom property via hash token? Actually custom properties are idents
                self.pos += 1;
                prop_tok.value.clone()
            }
            _ if prop_tok.value.starts_with("--") => {
                // Custom property (--foo)
                self.pos += 1;
                prop_tok.value.clone()
            }
            TokenKind::Delim if prop_tok.value == "-" => {
                // Vendor prefix like -webkit-...
                self.pos += 1;
                let rest = {
                    let mut r = "-".to_string();
                    // Consume ident
                    while self.pos < self.tokens.len() {
                        match self.tokens[self.pos].kind {
                            TokenKind::Ident | TokenKind::Delim if self.tokens[self.pos].value == "-" => {
                                r.push_str(&self.tokens[self.pos].value);
                                self.pos += 1;
                            }
                            _ => break,
                        }
                    }
                    r
                };
                rest
            }
            _ => {
                // Skip this token
                self.pos += 1;
                return Ok(None);
            }
        };

        self.skip_whitespace();

        // Expect colon
        if self.peek().kind != TokenKind::Colon {
            // Skip to semicolon or end of block
            while self.peek().kind != TokenKind::Semicolon 
                && self.peek().kind != TokenKind::RCurly
                && self.peek().kind != TokenKind::Eof {
                self.advance();
            }
            if self.peek().kind == TokenKind::Semicolon {
                self.advance();
            }
            return Ok(None);
        }
        self.advance(); // :

        self.skip_whitespace();

        // Parse value
        let (value, important) = self.parse_declaration_value()?;

        if property.is_empty() {
            return Ok(None);
        }

        Ok(Some(Declaration {
            property,
            value,
            important,
        }))
    }

    fn parse_declaration_value(&mut self) -> Result<(Vec<ComponentValue>, bool), CssError> {
        let mut values = Vec::new();
        let mut important = false;

        loop {
            if self.pos >= self.tokens.len() { break; }
            let tok = self.tokens[self.pos].clone();

            match tok.kind {
                TokenKind::Semicolon => { self.pos += 1; break; }
                TokenKind::RCurly => { break; }
                TokenKind::Eof => break,
                TokenKind::Comment => { self.pos += 1; }
                TokenKind::Delim if tok.value == "!" => {
                    self.pos += 1;
                    // Check for !important
                    self.skip_whitespace();
                    if self.pos < self.tokens.len() {
                        let next = self.tokens[self.pos].clone();
                        if next.kind == TokenKind::Ident && next.value.eq_ignore_ascii_case("important") {
                            self.pos += 1;
                            important = true;
                            // Skip any trailing whitespace/semicolon
                            self.skip_whitespace();
                            if self.peek().kind == TokenKind::Semicolon {
                                self.pos += 1;
                            }
                        } else {
                            // Not !important - return error
                            let (line, col) = self.current_position();
                            return Err(CssError::ParseError(format!(
                                "Error {{ kind: UnexpectedToken(Delim('!')), loc: Some(ErrorLocation {{ filename: {:?}, line: {}, column: {} }} ) }}",
                                self.filename, line, col
                            )));
                        }
                    }
                    break;
                }
                TokenKind::Function => {
                    self.pos += 1;
                    let fn_name = tok.value.clone();
                    let fn_args = self.parse_function_args()?;
                    values.push(ComponentValue::Function(fn_name, fn_args));
                }
                TokenKind::LParen => {
                    self.pos += 1;
                    let inner = self.parse_block_contents(TokenKind::RParen)?;
                    values.push(ComponentValue::Block(BlockKind::Paren, inner));
                }
                TokenKind::LBracket => {
                    self.pos += 1;
                    let inner = self.parse_block_contents(TokenKind::RBracket)?;
                    values.push(ComponentValue::Block(BlockKind::Square, inner));
                }
                _ => {
                    self.pos += 1;
                    values.push(ComponentValue::Token(tok));
                }
            }
        }

        // Trim trailing whitespace from values
        while values.last().map(|v| matches!(v, ComponentValue::Token(t) if t.kind == TokenKind::Whitespace)).unwrap_or(false) {
            values.pop();
        }

        Ok((values, important))
    }

    fn parse_function_args(&mut self) -> Result<Vec<ComponentValue>, CssError> {
        self.parse_block_contents(TokenKind::RParen)
    }

    fn parse_block_contents(&mut self, closing: TokenKind) -> Result<Vec<ComponentValue>, CssError> {
        let mut values = Vec::new();
        loop {
            if self.pos >= self.tokens.len() { break; }
            let tok = self.tokens[self.pos].clone();

            if tok.kind == closing {
                self.pos += 1;
                break;
            }

            match tok.kind {
                TokenKind::Eof => break,
                TokenKind::Comment => { self.pos += 1; }
                TokenKind::Function => {
                    self.pos += 1;
                    let fn_name = tok.value.clone();
                    let fn_args = self.parse_function_args()?;
                    values.push(ComponentValue::Function(fn_name, fn_args));
                }
                TokenKind::LParen => {
                    self.pos += 1;
                    let inner = self.parse_block_contents(TokenKind::RParen)?;
                    values.push(ComponentValue::Block(BlockKind::Paren, inner));
                }
                TokenKind::LBracket => {
                    self.pos += 1;
                    let inner = self.parse_block_contents(TokenKind::RBracket)?;
                    values.push(ComponentValue::Block(BlockKind::Square, inner));
                }
                _ => {
                    self.pos += 1;
                    values.push(ComponentValue::Token(tok));
                }
            }
        }
        Ok(values)
    }

    fn parse_declarations(&mut self) -> Result<Vec<Declaration>, CssError> {
        let mut decls = Vec::new();
        loop {
            self.skip_whitespace();
            match self.peek().kind {
                TokenKind::RCurly => { self.advance(); break; }
                TokenKind::Eof => break,
                TokenKind::Semicolon => { self.advance(); }
                _ => {
                    if let Some(decl) = self.parse_declaration()? {
                        decls.push(decl);
                    }
                }
            }
        }
        Ok(decls)
    }
}

fn position_from_token(tok: &Token, filename: &str) -> (u32, u32) {
    // We just track byte position, not line/column for now
    (0, tok.pos as u32)
}

pub fn parse(input: &str, filename: &str) -> Result<Stylesheet, CssError> {
    let mut tokenizer = Tokenizer::new(input);
    let tokens = tokenizer.tokenize_all();

    let mut parser = Parser::new(tokens, filename);
    let rules = parser.parse_stylesheet()?;

    Ok(Stylesheet {
        rules,
        source: input.to_string(),
        filename: filename.to_string(),
    })
}

pub fn parse_with_recovery(input: &str, filename: &str) -> (Stylesheet, Vec<String>) {
    // Parse with error recovery
    let mut errors = Vec::new();

    match parse(input, filename) {
        Ok(s) => (s, errors),
        Err(e) => {
            errors.push(e.to_string());
            // Return empty stylesheet
            (Stylesheet {
                rules: Vec::new(),
                source: input.to_string(),
                filename: filename.to_string(),
            }, errors)
        }
    }
}
