use super::parser::*;

pub fn print_formatted(stylesheet: &Stylesheet) -> String {
    let mut out = String::new();
    print_rules_formatted(&stylesheet.rules, &mut out, 0);
    out
}

pub fn print_minified(stylesheet: &Stylesheet) -> String {
    let mut out = String::new();
    print_rules_minified(&stylesheet.rules, &mut out);
    out
}

fn indent(level: usize) -> String {
    "  ".repeat(level)
}

fn print_rules_formatted(rules: &[Rule], out: &mut String, level: usize) {
    let mut first = true;
    for rule in rules {
        if !first {
            out.push('\n');
        }
        first = false;
        print_rule_formatted(rule, out, level);
    }
}

fn print_rule_formatted(rule: &Rule, out: &mut String, level: usize) {
    let ind = indent(level);
    match rule {
        Rule::Style(s) => {
            // Print selector
            let selectors = s.selectors.join(", ");
            out.push_str(&format!("{}{} {{\n", ind, selectors));

            for decl in &s.declarations {
                let value_str = normalize_value_formatted(&decl.property, &decl.value);
                if decl.important {
                    out.push_str(&format!("{}  {}: {} !important;\n", ind, decl.property, value_str));
                } else {
                    out.push_str(&format!("{}  {}: {};\n", ind, decl.property, value_str));
                }
            }

            if !s.nested_rules.is_empty() {
                if !s.declarations.is_empty() {
                    out.push('\n');
                }
                print_rules_formatted(&s.nested_rules, out, level + 1);
            }

            out.push_str(&format!("{}}}\n", ind));
        }
        Rule::AtRule(at) => {
            print_at_rule_formatted(at, out, level);
        }
        Rule::Unknown(s) => {
            out.push_str(s);
            out.push('\n');
        }
    }
}

fn print_at_rule_formatted(at: &AtRule, out: &mut String, level: usize) {
    let ind = indent(level);
    match &at.kind {
        AtRuleKind::Import(url) => {
            out.push_str(&format!("{}@import \"{}\";\n", ind, url));
        }
        AtRuleKind::Media(mq) => {
            out.push_str(&format!("{}@media {} {{\n", ind, normalize_media_query(&mq.raw)));
            if let Some(rules) = &at.block {
                print_rules_formatted(rules, out, level + 1);
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::Supports(cond) => {
            out.push_str(&format!("{}@supports {} {{\n", ind, cond));
            if let Some(rules) = &at.block {
                print_rules_formatted(rules, out, level + 1);
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::Keyframes(name) => {
            let vendor = if at.prelude.is_empty() { 
                String::new() 
            } else {
                format!("-{}-", at.prelude)
            };
            out.push_str(&format!("{}@{}keyframes {} {{\n", ind, vendor, name));
            if let Some(rules) = &at.block {
                for rule in rules {
                    match rule {
                        Rule::Style(s) => {
                            let sel = s.selectors.join(", ");
                            let norm_sel = normalize_keyframe_selector(&sel);
                            out.push_str(&format!("{}  {} {{\n", ind, norm_sel));
                            for decl in &s.declarations {
                                let value_str = normalize_value_formatted(&decl.property, &decl.value);
                                out.push_str(&format!("{}    {}: {};\n", ind, decl.property, value_str));
                            }
                            out.push_str(&format!("{}  }}\n", ind));
                            out.push('\n');
                        }
                        _ => {}
                    }
                }
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::FontFace => {
            out.push_str(&format!("{}@font-face {{\n", ind));
            if let Some(decls) = &at.declarations {
                for decl in decls {
                    let value_str = normalize_value_formatted(&decl.property, &decl.value);
                    out.push_str(&format!("{}  {}: {};\n", ind, decl.property, value_str));
                }
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::Layer(names) => {
            match names {
                None => { out.push_str(&format!("{}@layer;\n", ind)); }
                Some(ns) if ns.is_empty() => {
                    // Block form with no name
                    out.push_str(&format!("{}@layer {{\n", ind));
                    if let Some(rules) = &at.block {
                        print_rules_formatted(rules, out, level + 1);
                    }
                    out.push_str(&format!("{}}}\n", ind));
                }
                Some(ns) if at.block.is_some() => {
                    let name = ns.first().map(|s| s.as_str()).unwrap_or("");
                    out.push_str(&format!("{}@layer {} {{\n", ind, name));
                    if let Some(rules) = &at.block {
                        print_rules_formatted(rules, out, level + 1);
                    }
                    out.push_str(&format!("{}}}\n", ind));
                }
                Some(ns) => {
                    out.push_str(&format!("{}@layer {};\n", ind, ns.join(", ")));
                }
            }
        }
        AtRuleKind::CustomMedia(name, query) => {
            out.push_str(&format!("{}@custom-media {} ({});\n", ind, name, normalize_media_condition(query)));
        }
        AtRuleKind::Page(sel) => {
            if let Some(s) = sel {
                out.push_str(&format!("{}@page {} {{\n", ind, s));
            } else {
                out.push_str(&format!("{}@page {{\n", ind));
            }
            if let Some(decls) = &at.declarations {
                for decl in decls {
                    let value_str = normalize_value_formatted(&decl.property, &decl.value);
                    out.push_str(&format!("{}  {}: {};\n", ind, decl.property, value_str));
                }
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::CounterStyle(name) => {
            out.push_str(&format!("{}@counter-style {} {{\n", ind, name));
            if let Some(decls) = &at.declarations {
                for decl in decls {
                    let value_str = normalize_value_formatted(&decl.property, &decl.value);
                    out.push_str(&format!("{}  {}: {};\n", ind, decl.property, value_str));
                }
            }
            out.push_str(&format!("{}}}\n", ind));
        }
        AtRuleKind::Charset(_) => {
            // @charset is dropped
        }
        AtRuleKind::Unknown(name) | AtRuleKind::Namespace(_, _) => {
            if at.block.is_none() && at.declarations.is_none() {
                if at.prelude.is_empty() {
                    out.push_str(&format!("{}{};\n", ind, name));
                } else {
                    out.push_str(&format!("{}{} {};\n", ind, name, at.prelude));
                }
            } else {
                if at.prelude.is_empty() {
                    out.push_str(&format!("{}{} {{\n", ind, name));
                } else {
                    out.push_str(&format!("{}{} {} {{\n", ind, name, at.prelude));
                }
                out.push_str(&format!("{}}}\n", ind));
            }
        }
    }
}

fn print_rules_minified(rules: &[Rule], out: &mut String) {
    for rule in rules {
        print_rule_minified(rule, out);
    }
}

fn print_rule_minified(rule: &Rule, out: &mut String) {
    match rule {
        Rule::Style(s) => {
            let selectors = s.selectors.join(",");
            out.push_str(&selectors);
            out.push('{');

            let mut decl_parts = Vec::new();
            for decl in &s.declarations {
                let value_str = normalize_value_minified(&decl.property, &decl.value);
                if decl.important {
                    decl_parts.push(format!("{}:{} !important", decl.property, value_str));
                } else {
                    decl_parts.push(format!("{}:{}", decl.property, value_str));
                }
            }
            out.push_str(&decl_parts.join(";"));

            if !s.nested_rules.is_empty() {
                print_rules_minified(&s.nested_rules, out);
            }

            out.push('}');
        }
        Rule::AtRule(at) => {
            print_at_rule_minified(at, out);
        }
        Rule::Unknown(s) => {
            out.push_str(s);
        }
    }
}

fn print_at_rule_minified(at: &AtRule, out: &mut String) {
    match &at.kind {
        AtRuleKind::Import(url) => {
            out.push_str(&format!("@import \"{}\"", url));
            out.push(';');
        }
        AtRuleKind::Media(mq) => {
            out.push_str(&format!("@media {}", normalize_media_query_minified(&mq.raw)));
            out.push('{');
            if let Some(rules) = &at.block {
                print_rules_minified(rules, out);
            }
            out.push('}');
        }
        AtRuleKind::Supports(cond) => {
            out.push_str(&format!("@supports {}", cond));
            out.push('{');
            if let Some(rules) = &at.block {
                print_rules_minified(rules, out);
            }
            out.push('}');
        }
        AtRuleKind::Keyframes(name) => {
            let vendor = if at.prelude.is_empty() { 
                String::new() 
            } else {
                format!("-{}-", at.prelude)
            };
            out.push_str(&format!("@{}keyframes {}", vendor, name));
            out.push('{');
            if let Some(rules) = &at.block {
                for rule in rules {
                    match rule {
                        Rule::Style(s) => {
                            let sel = s.selectors.join(",");
                            let norm_sel = normalize_keyframe_selector_minified(&sel);
                            out.push_str(&norm_sel);
                            out.push('{');
                            let decl_parts: Vec<String> = s.declarations.iter().map(|d| {
                                let v = normalize_value_minified(&d.property, &d.value);
                                format!("{}:{}", d.property, v)
                            }).collect();
                            out.push_str(&decl_parts.join(";"));
                            out.push('}');
                        }
                        _ => {}
                    }
                }
            }
            out.push('}');
        }
        AtRuleKind::FontFace => {
            out.push_str("@font-face{");
            if let Some(decls) = &at.declarations {
                let parts: Vec<String> = decls.iter().map(|d| {
                    format!("{}:{}", d.property, normalize_value_minified(&d.property, &d.value))
                }).collect();
                out.push_str(&parts.join(";"));
            }
            out.push('}');
        }
        AtRuleKind::Layer(names) => {
            match names {
                None => { out.push_str("@layer;"); }
                Some(ns) if at.block.is_some() => {
                    if let Some(n) = ns.first() {
                        out.push_str(&format!("@layer {}", n));
                    } else {
                        out.push_str("@layer");
                    }
                    out.push('{');
                    if let Some(rules) = &at.block {
                        print_rules_minified(rules, out);
                    }
                    out.push('}');
                }
                Some(ns) => {
                    out.push_str(&format!("@layer {}", ns.join(",")));
                    out.push(';');
                }
            }
        }
        AtRuleKind::CustomMedia(name, query) => {
            out.push_str(&format!("@custom-media {} ({})", name, normalize_media_condition_minified(query)));
            out.push(';');
        }
        AtRuleKind::Page(sel) => {
            if let Some(s) = sel {
                out.push_str(&format!("@page {}", s));
            } else {
                out.push_str("@page");
            }
            out.push('{');
            if let Some(decls) = &at.declarations {
                let parts: Vec<String> = decls.iter().map(|d| {
                    format!("{}:{}", d.property, normalize_value_minified(&d.property, &d.value))
                }).collect();
                out.push_str(&parts.join(";"));
            }
            out.push('}');
        }
        AtRuleKind::CounterStyle(name) => {
            out.push_str(&format!("@counter-style {}", name));
            out.push('{');
            if let Some(decls) = &at.declarations {
                let parts: Vec<String> = decls.iter().map(|d| {
                    format!("{}:{}", d.property, normalize_value_minified(&d.property, &d.value))
                }).collect();
                out.push_str(&parts.join(";"));
            }
            out.push('}');
        }
        AtRuleKind::Charset(_) => {}
        AtRuleKind::Unknown(name) | AtRuleKind::Namespace(_, _) => {
            if at.prelude.is_empty() {
                out.push_str(name);
            } else {
                out.push_str(&format!("{} {}", name, at.prelude));
            }
            if at.block.is_none() && at.declarations.is_none() {
                out.push(';');
            }
        }
    }
}

// Value normalization
pub fn normalize_value_formatted(prop: &str, values: &[ComponentValue]) -> String {
    let raw = component_values_to_string(values);
    normalize_value_str(prop, &raw, false)
}

pub fn normalize_value_minified(prop: &str, values: &[ComponentValue]) -> String {
    let raw = component_values_to_string(values);
    normalize_value_str(prop, &raw, true)
}

fn normalize_value_str(prop: &str, value: &str, minify: bool) -> String {
    // Normalize colors
    let normalized = normalize_colors_in_value(value, minify);
    // Normalize quotes
    let normalized = normalize_quotes(&normalized);
    // Normalize numbers
    let normalized = normalize_numbers_in_value(&normalized, minify);
    // Property-specific normalizations
    let normalized = normalize_property_value(prop, &normalized, minify);
    normalized
}

fn normalize_quotes(s: &str) -> String {
    // Convert single-quoted strings to double-quoted
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\'' {
            result.push('"');
            while let Some(inner) = chars.next() {
                if inner == '\'' { 
                    result.push('"');
                    break;
                } else if inner == '"' {
                    result.push('\\');
                    result.push('"');
                } else {
                    result.push(inner);
                }
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn normalize_numbers_in_value(s: &str, minify: bool) -> String {
    if !minify {
        return s.to_string();
    }
    // Replace 0.X with .X when minifying
    let mut result = String::new();
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'0' && bytes[i+1] == b'.' {
            // Check if preceded by digit
            if i == 0 || (!bytes[i-1].is_ascii_digit() && bytes[i-1] != b'.' ) {
                // Skip leading 0
                // But only if not preceded by a negative sign directly (e.g. -0.5 -> -.5)
                result.push('.');
                i += 2; // skip "0."
                continue;
            }
        }
        result.push(bytes[i] as char);
        i += 1;
    }
    result
}

fn normalize_property_value(prop: &str, value: &str, minify: bool) -> String {
    match prop.to_lowercase().as_str() {
        "content" => normalize_content_value(value),
        "font" => normalize_font_value(value, minify),
        "font-family" => normalize_font_family(value),
        "background" => normalize_background_value(value, minify),
        "animation" => normalize_animation_value(value, minify),
        "transition" => normalize_transition_value(value, minify),
        "font-weight" => normalize_font_weight(value),
        "border" => normalize_border_value(value, minify),
        _ => value.to_string(),
    }
}

fn normalize_content_value(v: &str) -> String {
    v.to_string()
}

fn normalize_font_value(v: &str, minify: bool) -> String {
    // Just normalize whitespace
    let parts: Vec<&str> = v.split_whitespace().collect();
    if minify {
        // Reconstruct font with proper spacing
        v.to_string()
    } else {
        v.to_string()
    }
}

fn normalize_font_family(v: &str) -> String {
    // Remove unnecessary quotes from font families that are valid identifiers
    let mut result = String::new();
    let mut chars = v.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '"' || c == '\'' {
            let quote = c;
            let mut name = String::new();
            while let Some(inner) = chars.next() {
                if inner == quote { break; }
                name.push(inner);
            }
            // Check if name needs quotes
            let needs_quotes = name.chars().any(|c| !c.is_alphanumeric() && c != '-' && c != '_');
            if needs_quotes {
                result.push('"');
                result.push_str(&name);
                result.push('"');
            } else {
                result.push_str(&name);
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn normalize_background_value(v: &str, minify: bool) -> String {
    // Reorder background position if needed
    // This is simplified - just return as is
    v.to_string()
}

fn normalize_animation_value(v: &str, minify: bool) -> String {
    v.to_string()
}

fn normalize_transition_value(v: &str, minify: bool) -> String {
    v.to_string()
}

fn normalize_font_weight(v: &str) -> String {
    match v.trim() {
        "bold" => "700".to_string(),
        "normal" => "400".to_string(),
        _ => v.to_string(),
    }
}

fn normalize_border_value(v: &str, minify: bool) -> String {
    v.to_string()
}

pub fn normalize_media_query(q: &str) -> String {
    normalize_media_condition_direction(q, false)
}

pub fn normalize_media_query_minified(q: &str) -> String {
    normalize_media_condition_direction(q, true)
}

fn normalize_media_condition_direction(q: &str, minify: bool) -> String {
    // Convert min-width/max-width/etc to range syntax
    let result = convert_media_to_range_syntax(q, minify);
    if minify {
        collapse_whitespace(&result)
    } else {
        result
    }
}

fn collapse_whitespace(s: &str) -> String {
    let mut result = String::new();
    let mut in_space = false;
    for c in s.chars() {
        if c.is_whitespace() {
            if !in_space && !result.is_empty() {
                result.push(' ');
                in_space = true;
            }
        } else {
            in_space = false;
            result.push(c);
        }
    }
    result.trim().to_string()
}

fn convert_media_to_range_syntax(q: &str, minify: bool) -> String {
    // Convert (min-width: X) to (width >= X) or minified (width>=X)
    // Convert (max-width: X) to (width <= X) or minified (width<=X)
    // etc.

    let space = if minify { "" } else { " " };

    // Process each part of the media query
    // We need to handle nested expressions
    let mut result = q.to_string();

    // Replace (min-width: X) with (width >= X)
    result = replace_media_feature(&result, "min-width", "width", ">=", ">=", minify);
    result = replace_media_feature(&result, "max-width", "width", "<=", "<=", minify);
    result = replace_media_feature(&result, "min-height", "height", ">=", ">=", minify);
    result = replace_media_feature(&result, "max-height", "height", "<=", "<=", minify);

    result
}

fn replace_media_feature(q: &str, feature: &str, prop: &str, op: &str, op_min: &str, minify: bool) -> String {
    // Replace (feature: value) with (prop op value)
    let pattern = format!("({}: ", feature);
    let pattern_nospace = format!("({}:", feature);

    let mut result = String::new();
    let mut s = q;

    while !s.is_empty() {
        if let Some(idx) = s.to_lowercase().find(&pattern) {
            result.push_str(&s[..idx]);
            s = &s[idx + pattern.len()..];
            // Find closing )
            if let Some(close_idx) = s.find(')') {
                let value = &s[..close_idx];
                if minify {
                    result.push_str(&format!("({}{}{})", prop, op_min, value.trim()));
                } else {
                    result.push_str(&format!("({} {} {})", prop, op, value.trim()));
                }
                s = &s[close_idx + 1..];
            } else {
                result.push_str(s);
                s = "";
            }
        } else if let Some(idx) = s.to_lowercase().find(&pattern_nospace) {
            result.push_str(&s[..idx]);
            s = &s[idx + pattern_nospace.len()..];
            // Skip spaces after colon
            while s.starts_with(' ') { s = &s[1..]; }
            if let Some(close_idx) = s.find(')') {
                let value = &s[..close_idx];
                if minify {
                    result.push_str(&format!("({}{}{})", prop, op_min, value.trim()));
                } else {
                    result.push_str(&format!("({} {} {})", prop, op, value.trim()));
                }
                s = &s[close_idx + 1..];
            } else {
                result.push_str(s);
                s = "";
            }
        } else {
            result.push_str(s);
            break;
        }
    }

    result
}

pub fn normalize_media_condition(q: &str) -> String {
    // Just return as-is for @custom-media
    q.to_string()
}

pub fn normalize_media_condition_minified(q: &str) -> String {
    normalize_media_query_minified(q)
}

fn normalize_keyframe_selector(s: &str) -> String {
    // from -> 0%, to -> 100%  
    match s.trim() {
        "from" => "from".to_string(), // keep as is in formatted mode
        "to" => "to".to_string(),
        _ => s.to_string(),
    }
}

fn normalize_keyframe_selector_minified(s: &str) -> String {
    // from -> 0%, to stays as to
    match s.trim() {
        "from" => "0%".to_string(),
        _ => s.to_string(),
    }
}

// Color normalization
pub fn normalize_colors_in_value(value: &str, minify: bool) -> String {
    // Parse and normalize CSS colors in the value
    let mut result = String::new();
    let mut pos = 0;
    let bytes = value.as_bytes();

    while pos < bytes.len() {
        // Check for hex color
        if bytes[pos] == b'#' {
            let start = pos;
            pos += 1;
            let hex_start = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            let hex = &value[hex_start..pos];
            result.push_str(&normalize_hex_color(hex));
            continue;
        }

        // Check for color function
        let remaining = &value[pos..];
        if let Some(normalized) = try_normalize_color_function(remaining, minify) {
            result.push_str(&normalized.0);
            pos += normalized.1;
            continue;
        }

        // Check for named colors
        // (handled implicitly by rgb/hsl functions above)

        result.push(bytes[pos] as char);
        pos += 1;
    }

    result
}

fn normalize_hex_color(hex: &str) -> String {
    let n = hex.len();
    match n {
        3 => {
            // Try to make shorter
            format!("#{}", hex.to_lowercase())
        }
        4 => {
            // 4-digit hex with alpha
            format!("#{}", hex.to_lowercase())
        }
        6 => {
            // Check if can be shortened to 3 digits
            let chars: Vec<char> = hex.chars().collect();
            if chars[0] == chars[1] && chars[2] == chars[3] && chars[4] == chars[5] {
                format!("#{}{}{}", chars[0].to_lowercase(), chars[2].to_lowercase(), chars[4].to_lowercase())
            } else {
                // Check for named color
                let lower = hex.to_lowercase();
                if let Some(name) = hex6_to_named(&lower) {
                    name.to_string()
                } else {
                    format!("#{}", lower)
                }
            }
        }
        8 => {
            // 8-digit hex with alpha
            let chars: Vec<char> = hex.chars().collect();
            // Check if can be shortened to 4 digits
            if chars[0] == chars[1] && chars[2] == chars[3] && chars[4] == chars[5] && chars[6] == chars[7] {
                let short = format!("#{}{}{}{}", 
                    chars[0].to_lowercase(), chars[2].to_lowercase(),
                    chars[4].to_lowercase(), chars[6].to_lowercase());
                short
            } else {
                format!("#{}", hex.to_lowercase())
            }
        }
        _ => format!("#{}", hex)
    }
}

fn hex6_to_named(hex: &str) -> Option<&'static str> {
    match hex {
        "000000" | "000" => Some("#000"),
        "ff0000" => Some("red"),
        "00ff00" => Some("#0f0"),
        "0000ff" => Some("#00f"),
        "ffffff" | "fff" => Some("#fff"),
        "ffff00" => Some("#ff0"),
        "00ffff" => Some("#0ff"),
        "ff00ff" => Some("#f0f"),
        "008000" => Some("green"),
        "000080" => Some("navy"),
        "800000" => Some("maroon"),
        "808000" => Some("olive"),
        "800080" => Some("purple"),
        "008080" => Some("teal"),
        "c0c0c0" => Some("silver"),
        "808080" => Some("gray"),
        "ffa500" => Some("orange"),
        "a52a2a" => Some("brown"),
        _ => None
    }
}

fn try_normalize_color_function(s: &str, minify: bool) -> Option<(String, usize)> {
    // Check for rgb(), rgba(), hsl(), hsla()
    let lower = s.to_lowercase();

    let (fn_name, is_rgb, is_hsl) = if lower.starts_with("rgb(") || lower.starts_with("rgba(") {
        let name = if lower.starts_with("rgba(") { "rgba" } else { "rgb" };
        (name, true, false)
    } else if lower.starts_with("hsl(") || lower.starts_with("hsla(") {
        let name = if lower.starts_with("hsla(") { "hsla" } else { "hsl" };
        (name, false, true)
    } else {
        return None;
    };

    let fn_len = fn_name.len() + 1; // including '('
    if s.len() <= fn_len {
        return None;
    }

    // Find the matching )
    let mut depth = 1;
    let mut end = fn_len;
    while end < s.len() && depth > 0 {
        match s.as_bytes()[end] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            _ => {}
        }
        end += 1;
    }

    let args_str = &s[fn_len..end-1];
    let consumed = end;

    // Parse the arguments
    if is_rgb {
        if let Some(color_str) = normalize_rgb_function(fn_name, args_str, minify) {
            return Some((color_str, consumed));
        }
    } else if is_hsl {
        if let Some(color_str) = normalize_hsl_function(fn_name, args_str, minify) {
            return Some((color_str, consumed));
        }
    }

    None
}

fn parse_number(s: &str) -> Option<f64> {
    s.trim().parse::<f64>().ok()
}

fn normalize_rgb_function(fn_name: &str, args: &str, minify: bool) -> Option<String> {
    // Support both comma-separated and space-separated syntax
    let (parts, alpha) = parse_color_args(args)?;

    if parts.len() < 3 { return None; }

    let r = parse_color_component(&parts[0])?;
    let g = parse_color_component(&parts[1])?;
    let b_val = parse_color_component(&parts[2])?;

    let r = (r.clamp(0.0, 255.0) as u8);
    let g = (g.clamp(0.0, 255.0) as u8);
    let b = (b_val.clamp(0.0, 255.0) as u8);

    if let Some(a) = alpha {
        let a_val = parse_alpha(&a)?;
        if (a_val - 1.0).abs() < 0.001 {
            // Fully opaque
            return Some(rgb_to_color_string(r, g, b, None));
        }
        // Convert to 8-digit hex
        let a_byte = (a_val.clamp(0.0, 1.0) * 255.0).round() as u8;
        return Some(format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a_byte));
    } else {
        return Some(rgb_to_color_string(r, g, b, None));
    }
}

fn parse_color_args(args: &str) -> Option<(Vec<String>, Option<String>)> {
    // Handle: r, g, b / r, g, b, a / r g b / r g b / a
    let s = args.trim();

    if s.contains('/') {
        // Space-separated with / for alpha
        let parts: Vec<&str> = s.splitn(2, '/').collect();
        let color_parts: Vec<String> = parts[0].split_whitespace()
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect();
        let alpha = parts.get(1).map(|s| s.trim().to_string());
        return Some((color_parts, alpha));
    }

    if s.contains(',') {
        // Comma-separated
        let parts: Vec<String> = s.split(',').map(|s| s.trim().to_string()).collect();
        if parts.len() == 4 {
            return Some((parts[..3].to_vec(), Some(parts[3].clone())));
        }
        return Some((parts, None));
    }

    // Space-separated
    let parts: Vec<String> = s.split_whitespace().map(|s| s.to_string()).collect();
    Some((parts, None))
}

fn parse_color_component(s: &str) -> Option<f64> {
    let s = s.trim();
    if s.ends_with('%') {
        let n: f64 = s[..s.len()-1].parse().ok()?;
        Some(n / 100.0 * 255.0)
    } else {
        s.parse::<f64>().ok()
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    let s = s.trim();
    if s.ends_with('%') {
        let n: f64 = s[..s.len()-1].parse().ok()?;
        Some(n / 100.0)
    } else {
        s.parse::<f64>().ok()
    }
}

fn rgb_to_color_string(r: u8, g: u8, b: u8, alpha: Option<u8>) -> String {
    if let Some(a) = alpha {
        return format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a);
    }

    // Try to use named color first
    let hex6 = format!("{:02x}{:02x}{:02x}", r, g, b);
    if let Some(named) = hex6_to_named(&hex6) {
        return named.to_string();
    }

    // Try 3-digit hex
    if r & 0x0f == r >> 4 && g & 0x0f == g >> 4 && b & 0x0f == b >> 4 {
        format!("#{:x}{:x}{:x}", r >> 4, g >> 4, b >> 4)
    } else {
        format!("#{}", hex6)
    }
}

fn normalize_hsl_function(fn_name: &str, args: &str, minify: bool) -> Option<String> {
    let (parts, alpha) = parse_color_args(args)?;
    if parts.len() < 3 { return None; }

    let h: f64 = parts[0].trim().parse().ok()?;
    let s_str = parts[1].trim();
    let l_str = parts[2].trim();

    let s = if s_str.ends_with('%') {
        s_str[..s_str.len()-1].parse::<f64>().ok()? / 100.0
    } else {
        s_str.parse::<f64>().ok()?
    };

    let l = if l_str.ends_with('%') {
        l_str[..l_str.len()-1].parse::<f64>().ok()? / 100.0
    } else {
        l_str.parse::<f64>().ok()?
    };

    let a = if let Some(ref alpha_str) = alpha {
        parse_alpha(alpha_str)?
    } else {
        1.0
    };

    let (r, g, b) = hsl_to_rgb(h, s, l);

    if (a - 1.0).abs() < 0.001 {
        Some(rgb_to_color_string(r, g, b, None))
    } else {
        let a_byte = (a.clamp(0.0, 1.0) * 255.0).round() as u8;
        Some(format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a_byte))
    }
}

fn hsl_to_rgb(h: f64, s: f64, l: f64) -> (u8, u8, u8) {
    let h = h % 360.0;
    let h = if h < 0.0 { h + 360.0 } else { h };

    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
    let x = c * (1.0 - ((h / 60.0) % 2.0 - 1.0).abs());
    let m = l - c / 2.0;

    let (r1, g1, b1) = if h < 60.0 { (c, x, 0.0) }
        else if h < 120.0 { (x, c, 0.0) }
        else if h < 180.0 { (0.0, c, x) }
        else if h < 240.0 { (0.0, x, c) }
        else if h < 300.0 { (x, 0.0, c) }
        else { (c, 0.0, x) };

    let r = ((r1 + m) * 255.0).round() as u8;
    let g = ((g1 + m) * 255.0).round() as u8;
    let b = ((b1 + m) * 255.0).round() as u8;

    (r, g, b)
}

pub fn named_color_to_hex(name: &str) -> Option<&'static str> {
    match name.to_lowercase().as_str() {
        "red" => Some("#ff0000"),
        "green" => Some("#008000"),
        "blue" => Some("#0000ff"),
        "black" => Some("#000000"),
        "white" => Some("#ffffff"),
        "yellow" => Some("#ffff00"),
        "cyan" | "aqua" => Some("#00ffff"),
        "magenta" | "fuchsia" => Some("#ff00ff"),
        "orange" => Some("#ffa500"),
        "purple" => Some("#800080"),
        "gray" | "grey" => Some("#808080"),
        "silver" => Some("#c0c0c0"),
        "maroon" => Some("#800000"),
        "olive" => Some("#808000"),
        "lime" => Some("#00ff00"),
        "navy" => Some("#000080"),
        "teal" => Some("#008080"),
        "transparent" => Some("transparent"),
        _ => None,
    }
}
