use super::parser::*;
use super::browser::Targets;
use super::ProcessOptions;

pub fn transform(stylesheet: &mut Stylesheet, targets: &Targets, options: &ProcessOptions) {
    transform_rules(&mut stylesheet.rules, targets, options);
}

fn transform_rules(rules: &mut Vec<Rule>, targets: &Targets, options: &ProcessOptions) {
    let mut i = 0;
    while i < rules.len() {
        match &mut rules[i] {
            Rule::Style(ref mut style) => {
                // Flatten CSS nesting if targets require it
                if !style.nested_rules.is_empty() && targets.needs_nesting_transform() {
                    let nested = std::mem::take(&mut style.nested_rules);
                    let parent_selectors = style.selectors.clone();
                    let new_rules = flatten_nesting(nested, &parent_selectors, targets, options);
                    rules.splice(i+1..i+1, new_rules);
                }

                // Transform declarations
                transform_declarations(&mut style.declarations, targets);
            }
            Rule::AtRule(ref mut at) => {
                match &mut at.kind {
                    AtRuleKind::Media(_) | AtRuleKind::Supports(_) => {
                        if let Some(ref mut inner) = at.block {
                            transform_rules(inner, targets, options);
                        }
                    }
                    AtRuleKind::Keyframes(_) => {
                        if let Some(ref mut inner) = at.block {
                            for rule in inner.iter_mut() {
                                if let Rule::Style(ref mut s) = rule {
                                    transform_declarations(&mut s.declarations, targets);
                                }
                            }
                        }
                    }
                    _ => {}
                }

                // Transform media queries
                transform_at_rule(at, targets);
            }
            _ => {}
        }
        i += 1;
    }
}

fn flatten_nesting(nested: Vec<Rule>, parent_selectors: &[String], targets: &Targets, options: &ProcessOptions) -> Vec<Rule> {
    let mut result = Vec::new();

    for rule in nested {
        match rule {
            Rule::Style(mut s) => {
                // Combine parent selectors with nested selectors
                let mut new_selectors = Vec::new();
                for parent in parent_selectors {
                    for nested_sel in &s.selectors {
                        let combined = if nested_sel.contains('&') {
                            nested_sel.replace('&', parent)
                        } else {
                            format!("{} {}", parent, nested_sel)
                        };
                        new_selectors.push(combined);
                    }
                }

                let sub_nested = std::mem::take(&mut s.nested_rules);
                s.selectors = new_selectors.clone();

                // Recursively handle sub-nested rules
                let sub_rules = flatten_nesting(sub_nested, &new_selectors, targets, options);

                result.push(Rule::Style(s));
                result.extend(sub_rules);
            }
            Rule::AtRule(at) => {
                result.push(Rule::AtRule(at));
            }
            _ => {}
        }
    }

    result
}

fn transform_declarations(decls: &mut Vec<Declaration>, targets: &Targets) {
    if !targets.needs_prefix_transforms() {
        return;
    }

    let mut additions = Vec::new();

    for (i, decl) in decls.iter().enumerate() {
        let props = get_vendor_prefixes(&decl.property, targets);
        for (prefix, prop) in props {
            additions.push((i, Declaration {
                property: prop,
                value: decl.value.clone(),
                important: decl.important,
            }));
        }
    }

    // Insert additions in reverse order to maintain correct positions
    for (idx, decl) in additions.into_iter().rev() {
        decls.insert(idx, decl);
    }
}

fn get_vendor_prefixes(property: &str, targets: &Targets) -> Vec<(String, String)> {
    let mut result = Vec::new();

    match property.to_lowercase().as_str() {
        "user-select" if targets.needs_webkit_prefix() => {
            result.push(("webkit".to_string(), format!("-webkit-{}", property)));
        }
        "transform" if targets.needs_webkit_prefix_transform() => {
            result.push(("webkit".to_string(), format!("-webkit-{}", property)));
        }
        "transition" if targets.needs_webkit_prefix_transition() => {
            result.push(("webkit".to_string(), format!("-webkit-{}", property)));
        }
        "animation" if targets.needs_webkit_prefix_animation() => {
            result.push(("webkit".to_string(), format!("-webkit-{}", property)));
        }
        _ => {}
    }

    result
}

fn transform_at_rule(at: &mut AtRule, targets: &Targets) {
    match &mut at.kind {
        AtRuleKind::Media(mq) => {
            if targets.needs_old_media_query_syntax() {
                // Convert range syntax back to min/max
                mq.raw = convert_range_to_min_max(&mq.raw);
                mq.queries = vec![mq.raw.clone()];
            }
        }
        _ => {}
    }
}

fn convert_range_to_min_max(q: &str) -> String {
    // Convert (width >= X) to (min-width: X)
    // Convert (width <= X) to (max-width: X)
    let mut result = q.to_string();

    // Width >= => min-width
    result = replace_range_feature(&result, "width", ">=", "min-width");
    result = replace_range_feature(&result, "width", "<=", "max-width");
    result = replace_range_feature(&result, "height", ">=", "min-height");
    result = replace_range_feature(&result, "height", "<=", "max-height");

    // Also handle spaces
    result = replace_range_feature_spaced(&result, "width", ">=", "min-width");
    result = replace_range_feature_spaced(&result, "width", "<=", "max-width");
    result = replace_range_feature_spaced(&result, "height", ">=", "min-height");
    result = replace_range_feature_spaced(&result, "height", "<=", "max-height");

    result
}

fn replace_range_feature(q: &str, prop: &str, op: &str, feature: &str) -> String {
    // Match (prop op value) pattern
    let pattern = format!("({} {} ", prop, op);
    let mut result = String::new();
    let mut s = q;

    while !s.is_empty() {
        if let Some(idx) = s.find(&pattern) {
            result.push_str(&s[..idx]);
            s = &s[idx + pattern.len()..];
            if let Some(close_idx) = s.find(')') {
                let value = &s[..close_idx];
                result.push_str(&format!("({}: {})", feature, value.trim()));
                s = &s[close_idx + 1..];
            } else {
                result.push_str(s);
                s = "";
            }
        } else {
            result.push_str(s);
            break;
        }
    }
    result
}

fn replace_range_feature_spaced(q: &str, prop: &str, op: &str, feature: &str) -> String {
    // Already done above
    q.to_string()
}

// Selector transforms for :not() with multiple args, etc.
pub fn transform_selectors(selectors: &[String], targets: &Targets) -> Vec<String> {
    if !targets.needs_selector_transforms() {
        return selectors.to_vec();
    }

    selectors.iter().map(|sel| {
        transform_selector(sel, targets)
    }).collect()
}

fn transform_selector(sel: &str, targets: &Targets) -> String {
    let mut result = sel.to_string();

    // Transform :not() with multiple args
    if targets.needs_not_transform() {
        result = expand_not_selector(&result);
    }

    result
}

fn expand_not_selector(sel: &str) -> String {
    // :not(.a, .b) -> separate rules
    sel.to_string()
}
