use super::ProcessOptions;

#[derive(Debug, Default, Clone)]
pub struct Targets {
    pub chrome: Option<u32>,
    pub firefox: Option<u32>,
    pub safari: Option<u32>,
    pub edge: Option<u32>,
    pub ie: Option<u32>,
    pub webkit_prefix_needed: bool,
    pub old_media_query_syntax: bool,
    pub nesting_unsupported: bool,
    pub selector_transforms: bool,
}

impl Targets {
    pub fn needs_nesting_transform(&self) -> bool {
        self.nesting_unsupported
    }

    pub fn needs_prefix_transforms(&self) -> bool {
        self.webkit_prefix_needed
    }

    pub fn needs_old_media_query_syntax(&self) -> bool {
        self.old_media_query_syntax
    }

    pub fn needs_selector_transforms(&self) -> bool {
        self.selector_transforms
    }

    pub fn needs_not_transform(&self) -> bool {
        // :not() with multiple args needs Chrome >= 88
        self.chrome.map(|v| v < 88).unwrap_or(false) ||
        self.safari.map(|v| v < 9).unwrap_or(false)
    }

    pub fn needs_webkit_prefix(&self) -> bool {
        // user-select needs -webkit- prefix for Chrome < 54
        self.chrome.map(|v| v < 54).unwrap_or(false) ||
        self.safari.map(|v| v < 13).unwrap_or(false)
    }

    pub fn needs_webkit_prefix_transform(&self) -> bool {
        self.chrome.map(|v| v < 36).unwrap_or(false) ||
        self.safari.map(|v| v < 9).unwrap_or(false)
    }

    pub fn needs_webkit_prefix_transition(&self) -> bool {
        self.chrome.map(|v| v < 26).unwrap_or(false) ||
        self.safari.map(|v| v < 9).unwrap_or(false)
    }

    pub fn needs_webkit_prefix_animation(&self) -> bool {
        self.chrome.map(|v| v < 43).unwrap_or(false) ||
        self.safari.map(|v| v < 9).unwrap_or(false)
    }

    pub fn needs_color_downgrade(&self) -> bool {
        // oklch/lab/etc. need downgrade for Chrome < 111
        self.chrome.map(|v| v < 111).unwrap_or(false) ||
        self.safari.map(|v| v < 15).unwrap_or(false)
    }

    pub fn is_empty(&self) -> bool {
        self.chrome.is_none() && self.firefox.is_none() && 
        self.safari.is_none() && self.edge.is_none() && self.ie.is_none()
    }
}

pub fn parse_targets(options: &ProcessOptions) -> Targets {
    let mut targets = Targets::default();

    if let Some(ref target_str) = options.targets {
        parse_target_string(target_str, &mut targets);
    }

    if !targets.is_empty() {
        update_derived_flags(&mut targets);
    }

    targets
}

fn parse_target_string(s: &str, targets: &mut Targets) {
    // Parse target strings like "chrome 80", "ie 11", "chrome 80, firefox 75", etc.
    for part in s.split(',') {
        let part = part.trim();
        let words: Vec<&str> = part.splitn(2, ' ').collect();
        if words.len() == 2 {
            let browser = words[0].to_lowercase();
            let version: u32 = words[1].trim().parse().unwrap_or(0);
            match browser.as_str() {
                "chrome" => targets.chrome = Some(version),
                "firefox" | "ff" => targets.firefox = Some(version),
                "safari" => targets.safari = Some(version),
                "edge" => targets.edge = Some(version),
                "ie" | "internet explorer" => targets.ie = Some(version),
                _ => {}
            }
        }
    }
}

fn update_derived_flags(targets: &mut Targets) {
    // Old media query syntax needed for Chrome < 113
    targets.old_media_query_syntax = targets.chrome.map(|v| v < 113).unwrap_or(false) ||
        targets.safari.map(|v| v < 16).unwrap_or(false) ||
        targets.firefox.map(|v| v < 63).unwrap_or(false) ||
        targets.ie.map(|_| true).unwrap_or(false);

    // CSS nesting: Chrome >= 112, Firefox >= 117, Safari >= 16.5
    targets.nesting_unsupported = targets.chrome.map(|v| v < 112).unwrap_or(false) ||
        targets.safari.map(|v| v < 16).unwrap_or(false) ||
        targets.firefox.map(|v| v < 117).unwrap_or(false) ||
        targets.ie.map(|_| true).unwrap_or(false) ||
        targets.edge.map(|v| v < 112).unwrap_or(false);

    targets.webkit_prefix_needed = targets.needs_webkit_prefix() || 
        targets.needs_webkit_prefix_transform() ||
        targets.needs_webkit_prefix_transition() ||
        targets.needs_webkit_prefix_animation();

    targets.selector_transforms = targets.needs_not_transform();
}
