use super::parser::*;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct ClassInfo {
    pub renamed: String,
    pub composes: Vec<String>,
    pub is_referenced: bool,
}

#[derive(Debug, Default, Clone)]
pub struct ModuleExports {
    pub classes: HashMap<String, ClassInfo>,
}

pub fn apply_modules(
    stylesheet: &mut Stylesheet, 
    path: &str,
    pattern: &str,
    dashed_idents: bool,
) -> ModuleExports {
    let hash = compute_hash(path);
    let mut exports = ModuleExports::default();

    rename_rules(&mut stylesheet.rules, &hash, pattern, dashed_idents, &mut exports);

    exports
}

fn compute_hash(path: &str) -> String {
    // Use a simple hash function - FNV-1a 32-bit
    let h = fnv1a_32(path.as_bytes());

    // Encode as base64url, 6 chars
    let b64_chars = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

    // We encode 32 bits as 6 base64url chars (with some bits for the last char)
    // But we need to match the lightningcss encoding somehow...
    // For now, use our own consistent encoding
    let bytes = h.to_be_bytes();

    // Standard base64url of 4 bytes = 6 chars (with 4 padding bits in last char)
    // We'll use a "proper" base64url encoding to get 6 chars
    let mut result = [0u8; 6];
    let n = ((bytes[0] as u64) << 24) | ((bytes[1] as u64) << 16) | 
             ((bytes[2] as u64) << 8) | (bytes[3] as u64);

    // Encode 30 bits as 5 chars, then remaining 2 bits + 0000 as last char
    // Actually, let's do it properly:
    // 4 bytes = 32 bits, encode in 6 base64url chars (5.33 -> 6, with 4 padding bits = 0)
    let input = &bytes[..];

    let mut i = 0;
    let mut out_idx = 0;

    // Process groups of 3 bytes -> 4 chars
    // For 4 bytes: first 3 bytes -> 4 chars, then last 1 byte -> 2 chars

    // First 3 bytes -> 4 chars
    let b0 = input[0] as u32;
    let b1 = input[1] as u32;
    let b2 = input[2] as u32;
    result[0] = b64_chars[((b0 >> 2) & 0x3F) as usize];
    result[1] = b64_chars[(((b0 << 4) | (b1 >> 4)) & 0x3F) as usize];
    result[2] = b64_chars[(((b1 << 2) | (b2 >> 6)) & 0x3F) as usize];
    result[3] = b64_chars[(b2 & 0x3F) as usize];

    // Last 1 byte -> 2 chars (with 4 padding bits = 0)
    let b3 = input[3] as u32;
    result[4] = b64_chars[((b3 >> 2) & 0x3F) as usize];
    result[5] = b64_chars[((b3 << 4) & 0x3F) as usize];

    let hash_str = std::str::from_utf8(&result).unwrap_or("aaaaaa").to_string();

    // If hash starts with a digit or special char that's not valid as CSS class name start
    // We handle this in format_class_name
    hash_str
}

fn fnv1a_32(data: &[u8]) -> u32 {
    let mut h: u32 = 0x811c9dc5;
    for &b in data {
        h ^= b as u32;
        h = h.wrapping_mul(0x01000193);
    }
    h
}

fn format_class_name(pattern: &str, hash: &str, local: &str) -> String {
    let mut name = pattern.to_string();
    name = name.replace("[hash]", hash);
    name = name.replace("[local]", local);

    // Ensure the name is a valid CSS identifier
    // If it starts with a digit, add underscore
    if name.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        format!("_{}", name)
    } else {
        name
    }
}

fn rename_rules(
    rules: &mut Vec<Rule>,
    hash: &str,
    pattern: &str,
    dashed_idents: bool,
    exports: &mut ModuleExports,
) {
    for rule in rules.iter_mut() {
        match rule {
            Rule::Style(s) => {
                for sel in s.selectors.iter_mut() {
                    *sel = rename_selector(sel, hash, pattern, dashed_idents, exports);
                }
                // Handle nested rules
                rename_rules(&mut s.nested_rules, hash, pattern, dashed_idents, exports);

                // Handle composes
                process_composes_declarations(&mut s.declarations, hash, pattern, dashed_idents, exports);

                // Handle dashed idents in declarations
                if dashed_idents {
                    rename_dashed_idents_in_decls(&mut s.declarations, hash, pattern, exports);
                }
            }
            Rule::AtRule(at) => {
                match &mut at.kind {
                    AtRuleKind::Keyframes(ref mut name) => {
                        // Rename keyframe names
                        let new_name = format_class_name(pattern, hash, name);
                        exports.classes.insert(name.clone(), ClassInfo {
                            renamed: new_name.clone(),
                            composes: vec![],
                            is_referenced: true,
                        });
                        *name = new_name;
                    }
                    _ => {
                        if let Some(ref mut inner) = at.block {
                            rename_rules(inner, hash, pattern, dashed_idents, exports);
                        }
                    }
                }
            }
            _ => {}
        }
    }
}

fn rename_selector(
    sel: &str,
    hash: &str,
    pattern: &str,
    dashed_idents: bool,
    exports: &mut ModuleExports,
) -> String {
    let mut result = String::new();
    let mut chars = sel.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '.' => {
                // Class selector
                let mut name = String::new();
                while let Some(&nc) = chars.peek() {
                    if nc.is_alphanumeric() || nc == '-' || nc == '_' {
                        name.push(nc);
                        chars.next();
                    } else {
                        break;
                    }
                }
                if !name.is_empty() {
                    let new_name = format_class_name(pattern, hash, &name);
                    exports.classes.entry(name.clone()).or_insert_with(|| ClassInfo {
                        renamed: new_name.clone(),
                        composes: vec![],
                        is_referenced: false,
                    });
                    result.push('.');
                    result.push_str(&new_name);
                } else {
                    result.push('.');
                }
            }
            '#' => {
                // ID selector
                let mut name = String::new();
                while let Some(&nc) = chars.peek() {
                    if nc.is_alphanumeric() || nc == '-' || nc == '_' {
                        name.push(nc);
                        chars.next();
                    } else {
                        break;
                    }
                }
                if !name.is_empty() {
                    let new_name = format_class_name(pattern, hash, &name);
                    exports.classes.entry(name.clone()).or_insert_with(|| ClassInfo {
                        renamed: new_name.clone(),
                        composes: vec![],
                        is_referenced: false,
                    });
                    result.push('#');
                    result.push_str(&new_name);
                } else {
                    result.push('#');
                }
            }
            ':' if dashed_idents => {
                // Could be :global or :local pseudo
                result.push(c);
            }
            _ => {
                result.push(c);
            }
        }
    }

    result
}

fn process_composes_declarations(
    decls: &mut Vec<Declaration>,
    hash: &str,
    pattern: &str,
    dashed_idents: bool,
    exports: &mut ModuleExports,
) {
    // Find and remove 'composes' declarations
    decls.retain(|d| d.property != "composes");
}

fn rename_dashed_idents_in_decls(
    decls: &mut Vec<Declaration>,
    hash: &str,
    pattern: &str,
    exports: &mut ModuleExports,
) {
    // Rename CSS custom properties (--foo) in declarations
    for decl in decls.iter_mut() {
        if decl.property.starts_with("--") {
            let name = decl.property.trim_start_matches('-').to_string();
            let local = decl.property[2..].to_string();
            let new_name = format!("--{}", format_class_name(pattern, hash, &local));
            exports.classes.entry(decl.property.clone()).or_insert_with(|| ClassInfo {
                renamed: new_name.clone(),
                composes: vec![],
                is_referenced: true,
            });
            decl.property = new_name;
        }
    }
}
RUSTEOF
