use super::parser::*;
use super::CssError;
use super::ProcessOptions;
use std::path::{Path, PathBuf};
use std::fs;

pub fn bundle(
    stylesheet: &mut Stylesheet, 
    input_path: Option<&Path>,
    cwd: &Path,
    options: &ProcessOptions,
) -> Result<(), CssError> {
    let base_dir = if let Some(p) = input_path {
        p.parent().unwrap_or(cwd).to_path_buf()
    } else {
        cwd.to_path_buf()
    };

    resolve_imports(&mut stylesheet.rules, &base_dir)
}

fn resolve_imports(rules: &mut Vec<Rule>, base_dir: &Path) -> Result<(), CssError> {
    let mut i = 0;
    while i < rules.len() {
        if let Rule::AtRule(ref at) = rules[i] {
            if let AtRuleKind::Import(ref url) = at.kind {
                let url = url.clone();
                // Skip URLs (http/https)
                if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("//") {
                    i += 1;
                    continue;
                }

                let import_path = base_dir.join(&url);

                match fs::read_to_string(&import_path) {
                    Ok(content) => {
                        let filename = import_path.to_string_lossy().to_string();
                        match super::parser::parse(&content, &filename) {
                            Ok(imported) => {
                                // Resolve nested imports in the imported file
                                let mut imported_rules = imported.rules;
                                let import_dir = import_path.parent().unwrap_or(base_dir);
                                resolve_imports(&mut imported_rules, import_dir)?;

                                // Replace the @import with the imported rules
                                rules.remove(i);
                                for (j, r) in imported_rules.into_iter().enumerate() {
                                    rules.insert(i + j, r);
                                }
                            }
                            Err(e) => {
                                // Keep the import as-is on error
                                i += 1;
                            }
                        }
                    }
                    Err(_) => {
                        // File not found, keep import as-is
                        i += 1;
                    }
                }
                continue;
            }
        }
        i += 1;
    }
    Ok(())
}
