use super::parser::*;
use std::path::Path;

pub fn generate_sourcemap(
    stylesheet: &Stylesheet, 
    source_path: &str,
    source_content: &str,
    output_path: Option<&Path>,
) -> String {
    // Generate a simple sourcemap
    // For now, just map everything to the start

    let mappings = "AAAA";

    let source_url = if source_path.starts_with("stdin") {
        source_path.to_string()
    } else {
        source_path.to_string()
    };

    let content_json = json_string(source_content);

    format!(
        "{{\"version\":3,\"mappings\":\"{}\",\"sources\":[\"{}\"],\"sourcesContent\":[{}],\"names\":[]}}",
        mappings,
        escape_json_string(source_path),
        content_json
    )
}

fn json_string(s: &str) -> String {
    let mut result = String::from('"');
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c => result.push(c),
        }
    }
    result
}
