use super::parser::*;
use super::printer::normalize_value_minified;

pub fn minify(stylesheet: &mut Stylesheet) {
    // Merge duplicate rules and optimize
    merge_duplicate_rules(&mut stylesheet.rules);
}

fn merge_duplicate_rules(rules: &mut Vec<Rule>) {
    // Merge adjacent rules with same selectors or same declarations
    let mut i = 0;
    while i < rules.len() {
        // Merge adjacent style rules with same selectors
        if i + 1 < rules.len() {
            let can_merge = match (&rules[i], &rules[i+1]) {
                (Rule::Style(a), Rule::Style(b)) => {
                    a.selectors == b.selectors && a.nested_rules.is_empty() && b.nested_rules.is_empty()
                }
                _ => false
            };

            if can_merge {
                let next = rules.remove(i + 1);
                if let (Rule::Style(ref mut a), Rule::Style(b)) = (&mut rules[i], next) {
                    a.declarations.extend(b.declarations);
                    // Remove duplicate declarations (last one wins)
                    dedup_declarations(&mut a.declarations);
                    continue; // Don't increment i, check again
                }
            }
        }

        // Merge rules with same declarations
        if i + 1 < rules.len() {
            let can_merge_decls = match (&rules[i], &rules[i+1]) {
                (Rule::Style(a), Rule::Style(b)) => {
                    a.nested_rules.is_empty() && b.nested_rules.is_empty() &&
                    declarations_equal(&a.declarations, &b.declarations)
                }
                _ => false
            };

            if can_merge_decls {
                let next = rules.remove(i + 1);
                if let (Rule::Style(ref mut a), Rule::Style(b)) = (&mut rules[i], next) {
                    a.selectors.extend(b.selectors);
                    continue;
                }
            }
        }

        // Process nested
        match &mut rules[i] {
            Rule::AtRule(at) => {
                if let Some(ref mut inner) = at.block {
                    merge_duplicate_rules(inner);
                }
            }
            Rule::Style(s) => {
                dedup_declarations(&mut s.declarations);
                if !s.nested_rules.is_empty() {
                    merge_duplicate_rules(&mut s.nested_rules);
                }
            }
            _ => {}
        }

        i += 1;
    }
}

fn dedup_declarations(decls: &mut Vec<Declaration>) {
    // Keep last occurrence of each property
    let mut seen = std::collections::HashMap::new();
    let mut order = Vec::new();

    for (i, decl) in decls.iter().enumerate() {
        seen.insert(decl.property.clone(), i);
    }

    // Also handle shorthand/longhand conflicts (simplified)
    decls.retain(|d| {
        if let Some(&last_idx) = seen.get(&d.property) {
            // This will keep duplicates temporarily; we'll filter by last index
            true
        } else {
            true
        }
    });

    // Keep only last occurrence
    let mut final_decls = Vec::new();
    let mut i = 0;
    while i < decls.len() {
        let prop = &decls[i].property;
        // Check if there's a later declaration with the same property
        let has_later = decls[i+1..].iter().any(|d| d.property == *prop);
        if !has_later {
            final_decls.push(decls[i].clone());
        }
        i += 1;
    }
    *decls = final_decls;
}

fn declarations_equal(a: &[Declaration], b: &[Declaration]) -> bool {
    if a.len() != b.len() { return false; }
    for (da, db) in a.iter().zip(b.iter()) {
        if da.property != db.property { return false; }
        let va = component_values_to_string(&da.value);
        let vb = component_values_to_string(&db.value);
        if va != vb { return false; }
    }
    true
}
