// lightningcss - CSS parser, transformer, and minifier
// Version 1.0.0-alpha.70

mod cli;
mod css;

use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::process;

fn main() {
    let args = cli::parse_args();

    if args.version {
        println!("lightningcss 1.0.0-alpha.70");
        return;
    }

    if args.help {
        cli::print_help();
        return;
    }

    // Validate arguments
    if args.sourcemap && args.output_file.is_none() && args.output_dir.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>");
        eprintln!();
        eprintln!("USAGE:");
        if args.css_modules.is_some() {
            eprintln!("    {} --sourcemap <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>> <--css-modules [<CSS_MODULES>]>", "executable");
        } else {
            eprintln!("    {} --sourcemap <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>", "executable");
        }
        eprintln!();
        eprintln!("For more information try --help");
        process::exit(2);
    }

    if args.input_files.len() > 1 && args.output_file.is_some() {
        eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
        process::exit(1);
    }

    let options = css::ProcessOptions {
        minify: args.minify,
        targets: args.targets.clone(),
        css_modules: args.css_modules.is_some(),
        css_modules_pattern: args.css_modules_pattern.clone(),
        css_modules_dashed_idents: args.css_modules_dashed_idents,
        bundle: args.bundle,
        sourcemap: args.sourcemap,
        error_recovery: args.error_recovery,
        custom_media: args.custom_media,
        browserslist: args.browserslist,
    };

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

    if args.input_files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).expect("Failed to read stdin");

        let pid = process::id();
        let filename = format!("stdin-{}", pid);

        let result = css::process_css(&input, &filename, &options, &cwd, None);

        match result {
            Ok(result) => {
                if args.css_modules.is_some() && args.output_file.is_none() && args.output_dir.is_none() {
                    // Print as JSON
                    let json = format!("{{\"code\":{},\"exports\":{}}}",
                        json_escape_string(&result.code),
                        result.exports_json);
                    println!("{}", json);
                } else {
                    let output_path = args.output_file.as_ref().map(|p| PathBuf::from(p));

                    let mut css_out = result.code.clone();
                    if let Some(ref map_data) = result.sourcemap {
                        if let Some(ref out_path) = output_path {
                            let map_filename = out_path.file_name()
                                .map(|f| format!("{}.map", f.to_string_lossy()))
                                .unwrap_or_else(|| "out.css.map".to_string());
                            css_out.push_str(&format!("\n/*# sourceMappingURL={} */", map_filename));

                            let map_path = format!("{}.map", out_path.display());
                            fs::write(&map_path, map_data).expect("Failed to write sourcemap");
                        }
                    }

                    if let Some(ref out_path) = output_path {
                        fs::write(out_path, css_out).expect("Failed to write output file");

                        if args.css_modules.is_some() {
                            let json_path = get_modules_json_path(
                                out_path,
                                args.css_modules.as_deref(),
