            result.push_str(&normalized.0);
            pos += normalized.1;
            continue;
        }

        // Check for named colors (when at word boundary)
        if bytes[pos].is_ascii_alphabetic() {
            // Try to match a named color
            let start = pos;
            while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'-') {
                pos += 1;
