# z-index, opacity, margin - input order preserved!
# But in previous test: max-width, margin, color, background-color -> color, background-color, max-width, margin
# 
# The difference: color and background-color are "background" property group shorthands.
# lightningcss probably combines them into a single group.
# 
# I think the reordering happens when lightningcss detects shorthand/longhand relationships
# and reorders within the logical group.
# 
# This is complex to implement. Let me skip property reordering for now and focus on
# the value normalizations.

# Let me implement value normalizations:
# 1. Strip units from zero values (0px -> 0, 0deg -> 0, etc.)
# 2. Strip leading zeros (0.5 -> .5)
# 3. Handle specific property formatting

# These normalizations should apply to ALL properties, not just specific ones.
# Let me update the normalize_value_str function.

python3 << 'EOF'
with open('/workspace/src/css/printer.rs', 'r') as f:
    content = f.read()

# Update normalize_numbers_in_value to always strip leading zeros (not just when minifying)
old = """fn normalize_numbers_in_value(s: &str, minify: bool) -> String {
    if !minify {
        return s.to_string();
    }
    // Replace 0.X with .X when minifying
    let mut result = String::new();
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'0' && bytes[i+1] == b'.' {
            // Check if preceded by digit
            if i == 0 || (!bytes[i-1].is_ascii_digit() && bytes[i-1] != b'.' ) {
                // Skip leading 0
                // But only if not preceded by a negative sign directly (e.g. -0.5 -> -.5)
                result.push('.');
                i += 2; // skip "0."
                continue;
            }
        }
        result.push(bytes[i] as char);
        i += 1;
    }
    result
}"""

new = """fn normalize_numbers_in_value(s: &str, minify: bool) -> String {
    // Always strip leading zeros (0.5 -> .5) in both formatted and minified output
    let mut result = String::new();
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'0' && bytes[i+1] == b'.' {
            // Check if not preceded by a digit (avoid "10.5" -> "1.5")
            let prev_is_digit = i > 0 && (bytes[i-1].is_ascii_digit() || bytes[i-1] == b'.');
            if !prev_is_digit {
                // Strip leading zero: "0." -> "."
                result.push('.');
                i += 2; // skip "0."
                continue;
            }
        }

        // Also strip units from zero values (0px -> 0, etc.)
        if bytes[i] == b'0' {
            let prev_is_digit_or_dot = i > 0 && (bytes[i-1].is_ascii_digit() || bytes[i-1] == b'.');
            if !prev_is_digit_or_dot {
                // Could be a zero that needs unit stripping
                result.push('0');
                i += 1;
                // Now consume the unit if it's a length/angle unit
                let unit_start = i;
                while i < bytes.len() && (bytes[i].is_ascii_alphabetic() || bytes[i] == b'%') {
                    i += 1;
                }
                if i > unit_start {
                    let unit = &s[unit_start..i];
                    // Only strip if it's a length/angle unit (not 's' for seconds in animation, etc.)
                    let should_strip = matches!(unit, 
                        "px" | "em" | "rem" | "vw" | "vh" | "vmin" | "vmax" |
                        "cm" | "mm" | "in" | "pt" | "pc" | "ex" | "ch" |
                        "deg" | "grad" | "rad" | "turn" | "fr" |
                        "dpi" | "dpcm" | "dppx"
                    );
                    if !should_strip {
                        result.push_str(unit);
                    }
                }
                continue;
            }
        }

        result.push(bytes[i] as char);
        i += 1;
    }
    result
}"""

content = content.replace(old, new)

with open('/workspace/src/css/printer.rs', 'w') as f:
    f.write(content)
print("Done")
EOF

