# Now I need to improve parse_with_recovery to actually parse multiple rules
# even when one fails.

python3 << 'EOF'
with open('/workspace/src/css/parser.rs', 'r') as f:
    content = f.read()

# Update parse_with_recovery
old = """pub fn parse_with_recovery(input: &str, filename: &str) -> (Stylesheet, Vec<String>) {
    // Parse with error recovery
    let mut errors = Vec::new();

    match parse(input, filename) {
        Ok(s) => (s, errors),
        Err(e) => {
            errors.push(e.to_string());
            // Return empty stylesheet
            (Stylesheet {
                rules: Vec::new(),
                source: input.to_string(),
                filename: filename.to_string(),
            }, errors)
        }
    }
}"""

new = """pub fn parse_with_recovery(input: &str, filename: &str) -> (Stylesheet, Vec<String>) {
    // Try to parse normally first
    let mut errors = Vec::new();

    match parse(input, filename) {
        Ok(s) => return (s, errors),
        Err(e) => {
            // Extract error message
            let err_msg = format_error_for_recovery(&e.to_string(), filename);
            errors.push(err_msg);
        }
    }

    // Error recovery: try to parse each rule individually
    let mut tokenizer = crate::css::tokenizer::Tokenizer::new(input);
    let tokens = tokenizer.tokenize_all();

    // Find valid rule boundaries and parse each one
    let rules = parse_rules_with_recovery(&tokens, filename, &mut errors);

    (Stylesheet {
        rules,
        source: input.to_string(),
        filename: filename.to_string(),
    }, errors)
}

fn format_error_for_recovery(msg: &str, filename: &str) -> String {
    // Parse the error and format it user-friendly
    if msg.contains("EndOfInput") {
        // Find line/col
        let (line, col) = extract_position(msg);
        format!("Unexpected end of input at {}:{}:{}", filename, line, col)
    } else if msg.contains("UnexpectedToken") {
        let (line, col) = extract_position(msg);
        let tok = extract_token(msg);
        format!("Unexpected token {} at {}:{}:{}", tok, filename, line, col)
    } else {
        msg.to_string()
    }
}

fn extract_position(msg: &str) -> (u32, u32) {
    let line = if let Some(idx) = msg.find("line: ") {
        let rest = &msg[idx+6..];
        let end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
        rest[..end].parse().unwrap_or(0)
    } else { 0 };

    let col = if let Some(idx) = msg.find("column: ") {
        let rest = &msg[idx+8..];
        let end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
        rest[..end].parse().unwrap_or(0)
    } else { 0 };

    (line, col)
}

fn extract_token(msg: &str) -> String {
    if let Some(idx) = msg.find("UnexpectedToken(") {
        let rest = &msg[idx+"UnexpectedToken(".len()..];
        if let Some(end) = rest.rfind(')') {
            return rest[..end].to_string();
        }
    }
    "unknown".to_string()
}

fn parse_rules_with_recovery(tokens: &[crate::css::tokenizer::Token], filename: &str, errors: &mut Vec<String>) -> Vec<Rule> {
    use crate::css::tokenizer::TokenKind;

    let mut rules = Vec::new();

    // Find rule boundaries by looking for balanced { } pairs at top level
    let mut i = 0;
    while i < tokens.len() {
        if tokens[i].kind == TokenKind::Eof { break; }
