        if c.is_alphabetic() || c == '-' || c == '_' {
            let mut s = String::new();
            while let Some(&nc) = chars.peek() {
                if nc.is_alphanumeric() || nc == '-' || nc == '_' {
                    s.push(nc);
                    chars.next();
                    pos += 1;
