fn normalize_single_animation(v: &str, minify: bool) -> String {
    // Parse animation value tokens
    let parts: Vec<&str> = v.split_whitespace().collect();

    // Identify the animation name (not a time, not a known keyword)
    // Time values end with 's' or 'ms'
    // Known keywords: ease, linear, ease-in, ease-out, ease-in-out, step-start, step-end,
    //                 normal, reverse, alternate, alternate-reverse, forwards, backwards, both, none,
