# It renames:
# :root { --foo: red } -> :root { --renamed_foo: red }
# .bar { color: var(--foo) } -> .bar { color: var(--foo) } (UNCHANGED!)
# 
# But my implementation now renames var(--foo) as well.
# Let me revert the var() renaming since the original doesn't do it.

python3 << 'EOF'
with open('/workspace/src/css/modules.rs', 'r') as f:
    content = f.read()

# Revert var() renaming - just rename the property, not var() references
old = """fn rename_dashed_idents_in_decls(
    decls: &mut Vec<Declaration>,
    hash: &str,
    pattern: &str,
    exports: &mut ModuleExports,
) {
    // Rename CSS custom properties (--foo) in declarations and var() references
    for decl in decls.iter_mut() {
        // Rename the property itself
        if decl.property.starts_with("--") {
            let local = decl.property[2..].to_string();
            let new_name = format!("--{}", format_class_name(pattern, hash, &local));
            exports.classes.entry(decl.property.clone()).or_insert_with(|| ClassInfo {
                renamed: new_name.clone(),
                composes: vec![],
                is_referenced: true,
            });
            decl.property = new_name;
        }

        // Rename var(--foo) references in values
        rename_dashed_idents_in_values(&mut decl.value, hash, pattern, exports);
    }
}

fn rename_dashed_idents_in_values(
    values: &mut Vec<super::parser::ComponentValue>,
    hash: &str,
    pattern: &str,
    exports: &mut ModuleExports,
) {
    use super::parser::ComponentValue;

    for val in values.iter_mut() {
        match val {
            ComponentValue::Function(name, args) => {
                if name.eq_ignore_ascii_case("var(") {
                    // First arg might be a --custom-property reference
                    rename_dashed_idents_in_values(args, hash, pattern, exports);
                } else {
                    rename_dashed_idents_in_values(args, hash, pattern, exports);
                }
            }
            ComponentValue::Token(t) if t.value.starts_with("--") => {
                let local = t.value[2..].to_string();
                let new_name = format!("--{}", format_class_name(pattern, hash, &local));
                // Look up or insert into exports
                let renamed = exports.classes.entry(t.value.clone()).or_insert_with(|| ClassInfo {
                    renamed: new_name.clone(),
                    composes: vec![],
                    is_referenced: true,
                }).renamed.clone();
                t.value = renamed;
            }
            ComponentValue::Block(_, inner) => {
                rename_dashed_idents_in_values(inner, hash, pattern, exports);
            }
            _ => {}
        }
    }
}"""

new = """fn rename_dashed_idents_in_decls(
    decls: &mut Vec<Declaration>,
    hash: &str,
    pattern: &str,
    exports: &mut ModuleExports,
) {
    // Rename CSS custom properties (--foo) in declarations
    for decl in decls.iter_mut() {
        if decl.property.starts_with("--") {
            let local = decl.property[2..].to_string();
            let new_name = format!("--{}", format_class_name(pattern, hash, &local));
            exports.classes.entry(decl.property.clone()).or_insert_with(|| ClassInfo {
                renamed: new_name.clone(),
                composes: vec![],
                is_referenced: true,
            });
            decl.property = new_name;
        }
    }
}"""

content = content.replace(old, new)

with open('/workspace/src/css/modules.rs', 'w') as f:
    f.write(content)
print("Done")
EOF

cd /workspace && cargo build --release 2>&1 | grep "^error\|Finished" | head -5

