# Let me also run a comparison against the original for a complex CSS file 
# to make sure everything works:

cat > /tmp/complex.css << 'EOF'
:root {
  --primary: #3498db;
  --secondary: rgba(52, 152, 219, 0.5);
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  font-family: "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: #333;
  background-color: #fff;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.button {
  display: inline-block;
  padding: 10px 20px;
  background-color: var(--primary);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.button:hover {
  background-color: #2980b9;
}

@media screen and (max-width: 768px) {
  .container {
    padding: 0 10px;
  }

  .button {
    width: 100%;
    text-align: center;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
EOF

echo "=== Complex test: diff ==="
diff <(/workspace/target/release/lightningcss /tmp/complex.css) \
     <(/workspace/executable /tmp/complex.css) && echo "PASS: no differences"

